4: import { Bot, Film, Frame, Images, LibraryBig, ScanSearch, Sparkles } from 'lucide-react';
5: import { TabsList, TabsTrigger } from '@/components/ui/tabs';
6: 
7: interface WorkspaceModeTabsProps {
8:   wideMode?: boolean;
9:   showPromptGallery?: boolean;
10: }
11: 
12: const horizontalTriggerClass =
13:   'group h-full min-h-0 min-w-0 gap-1 overflow-hidden whitespace-nowrap rounded-xl px-2 py-2 text-xs max-sm:w-14 max-sm:shrink-0 max-sm:flex-none max-sm:data-active:w-auto max-sm:data-active:min-w-[88px] sm:h-[calc(100%-1px)] sm:gap-2 sm:px-3 sm:py-2 sm:text-sm';
14: 
15: const labelClass = 'max-sm:hidden max-sm:group-data-active:inline';
16: 
17: const tabs = [
18:   { value: 'agent', icon: Bot, label: 'Agent' },
19:   { value: 'image-generation', icon: Sparkles, label: '生图工作台' },
20:   { value: 'canvas', icon: Frame, label: '无限画布' },
21:   { value: 'assets', icon: Images, label: '我的素材' },
22:   { value: 'reverse-prompt', icon: ScanSearch, label: '反推提示词' },
23:   { value: 'gif', icon: Film, label: '动图生成' },
24: ] as const;
25: 
26: const galleryTab = { value: 'prompt-gallery', icon: LibraryBig, label: '提示词广场' } as const;
27: 
28: export function WorkspaceModeTabs({ wideMode = false, showPromptGallery = false }: WorkspaceModeTabsProps) {
29:   const gridCols = showPromptGallery ? 'sm:grid-cols-7' : 'sm:grid-cols-6';
30:   const allTabs = showPromptGallery ? [...tabs, galleryTab] : tabs;
31:   const dragStateRef = useRef({
32:     pointerId: -1,
33:     startX: 0,
34:     scrollLeft: 0,
35:     dragged: false,
36:   });
37: 
38:   if (wideMode) {
39:     // 宽屏 → 垂直气泡侧边栏
40:     return (
41:       <TabsList className="w-full flex-col gap-1.5 rounded-2xl border border-border bg-muted/50 p-2">
42:         {allTabs.map(({ value, icon: Icon, label }) => (
43:           <TabsTrigger
44:             key={value}
45:             value={value}
46:             className="flex flex-row items-center gap-2 rounded-xl px-3 py-2.5 text-xs font-medium data-active:bg-card data-active:text-foreground data-active:shadow-sm"
47:           >
48:             <Icon className="size-5 shrink-0" />
49:             <span>{label}</span>
50:           </TabsTrigger>
51:         ))}
52:       </TabsList>
53:     );
54:   }
55: 
56:   // 窄屏 → 水平标签栏
57:   return (
58:     <TabsList
59:       className={`scrollbar-hide flex h-16 w-full max-w-full touch-pan-x select-none justify-start gap-1 overflow-x-auto overflow-y-hidden overscroll-x-contain rounded-2xl bg-muted p-1 sm:grid ${gridCols} sm:overflow-visible sm:border sm:border-border sm:select-auto`}
60:       onPointerDown={event => {
61:         const el = event.currentTarget;
62:         if (!el || (event.pointerType === 'mouse' && event.button !== 0) || el.scrollWidth <= el.clientWidth) return;
63: 
64:         dragStateRef.current = {
65:           pointerId: event.pointerId,
66:           startX: event.clientX,
67:           scrollLeft: el.scrollLeft,
68:           dragged: false,
69:         };
70:         el.setPointerCapture(event.pointerId);
71:       }}
72:       onPointerMove={event => {
73:         const el = event.currentTarget;
74:         const state = dragStateRef.current;
75:         if (state.pointerId !== event.pointerId) return;
76: 
77:         const deltaX = event.clientX - state.startX;
78:         if (Math.abs(deltaX) > 4) state.dragged = true;
79:         if (state.dragged) {
80:           el.scrollLeft = state.scrollLeft - deltaX;
81:           event.preventDefault();
82:         }
83:       }}
84:       onPointerUp={event => {
85:         if (dragStateRef.current.pointerId !== event.pointerId) return;
86:         event.currentTarget.releasePointerCapture(event.pointerId);
87:         dragStateRef.current.pointerId = -1;
88:       }}
89:       onPointerCancel={event => {
90:         if (dragStateRef.current.pointerId === event.pointerId) {
91:           event.currentTarget.releasePointerCapture(event.pointerId);
92:         }
93:         dragStateRef.current.pointerId = -1;
94:       }}
95:       onClickCapture={event => {
96:         if (!dragStateRef.current.dragged) return;
97:         event.preventDefault();
98:         event.stopPropagation();
99:         dragStateRef.current.dragged = false;
100:       }}
101:     >
102:       {allTabs.map(({ value, icon: Icon, label }) => (
103:         <TabsTrigger key={value} value={value} className={horizontalTriggerClass}>
104:           <Icon className="size-4 shrink-0" />
105:           <span className={labelClass}>{label}</span>
106:         </TabsTrigger>
107:       ))}
108:     </TabsList>
109:   );
110: }

