15: import { deleteStoredBlobs, revokeBlobUrls } from '@/lib/image-downloader';
16: 
17: function isWaitingJob(job: StoredJob): boolean {
18:   return job.status === 'processing' || job.status === 'queued' || job.status === '排队中';
19: }
20: 
21: function loadInitialJobs(): StoredJob[] {
22:   return loadJobs().map(job => ({
23:     ...job,
24:     ...(isWaitingJob(job) && !job.serverTaskId ? { status: 'failed' as const, error: '页面刷新，任务已中断', terminal: true } : {}),
25:     ...(!job.model ? { model: 'gemini-3-pro-image-preview' as ModelId } : {}),
26:   }));
27: }
28: 
29: export function useWorkspaceJobs() {
30:   const [hasApiKey, setHasApiKey] = useState(() => hasAnyApiKey());
31:   const [jobs, setJobs] = useState<StoredJob[]>(loadInitialJobs);
32:   const jobsRef = useRef(jobs);
33:   useEffect(() => { jobsRef.current = jobs; }, [jobs]);
34:   const [loadedImages, setLoadedImages] = useState<Set<string>>(new Set());
35:   const [retryData, setRetryData] = useState<RetryData | null>(null);
36:   const [clearAllDialogOpen, setClearAllDialogOpen] = useState<Mode | null>(null);
37:   const [cancelJobId, setCancelJobId] = useState<string | null>(null);
38: 
39:   useEffect(() => {
40:     const refreshApiKeyState = () => setHasApiKey(hasAnyApiKey());
41:     refreshApiKeyState();
42:     window.addEventListener('nova-model-registry-updated', refreshApiKeyState);
43:     return () => window.removeEventListener('nova-model-registry-updated', refreshApiKeyState);
