160:       if (job.blobUrls) {
161:         revokeBlobUrls(job.blobUrls);
162:       }
163:     }
164:     persistJobs(prev => prev.filter(job => job.mode !== modeFilter));
165:     setLoadedImages(prev => {
166:       const next = new Set(prev);
167:       for (const job of toRemove) {
168:         next.delete(job.id);
169:       }
170:       return next;
171:     });
