1: 'use client';
2: 
3: import { useState, useEffect } from 'react';
4: import { Sun, Moon, Monitor } from 'lucide-react';
5: import {
6:   DropdownMenu,
7:   DropdownMenuContent,
8:   DropdownMenuRadioGroup,
9:   DropdownMenuRadioItem,
10:   DropdownMenuTrigger,
11: } from '@/components/ui/dropdown-menu';
12: import { Button, buttonVariants } from '@/components/ui/button';
13: import { cn } from '@/lib/utils';
14: import { runtimeStorage } from '@/lib/runtime-storage';
15: 
16: type Theme = 'light' | 'dark' | 'system';
17: 
18: const themeOptions: { value: Theme; label: string; icon: typeof Sun }[] = [
19:   { value: 'light', label: '亮色', icon: Sun },
20:   { value: 'dark', label: '暗色', icon: Moon },
21:   { value: 'system', label: '跟随系统', icon: Monitor },
22: ];
23: 
24: function isTheme(value: string | null): value is Theme {
25:   return value === 'light' || value === 'dark' || value === 'system';
26: }
27: 
28: function applyTheme(newTheme: Theme) {
29:   const root = document.documentElement;
30:   if (newTheme === 'system') {
31:     root.removeAttribute('data-theme');
32:   } else {
33:     root.setAttribute('data-theme', newTheme);
34:   }
35: }
36: 
37: export function ThemeToggle() {
38:   const [theme, setTheme] = useState<Theme>('system');
39:   const [mounted, setMounted] = useState(false);
40: 
41:   useEffect(() => {
42:     let cancelled = false;
43: 
44:     queueMicrotask(() => {
45:       if (cancelled) return;
46: 
47:       setMounted(true);
48:       try {
49:         const stored = runtimeStorage.getItem('theme');
50:         if (!isTheme(stored)) return;
51:         setTheme(stored);
52:         applyTheme(stored);
53:       } catch {
54:         applyTheme('system');
55:       }
56:     });
57: 
58:     return () => {
59:       cancelled = true;
60:     };
61:   }, []);
62: 
63:   const selectTheme = (newTheme: string) => {
64:     if (!isTheme(newTheme)) return;
65:     setTheme(newTheme);
66:     try {
67:       runtimeStorage.setItem('theme', newTheme);
68:     } catch {
69:       // Storage can be unavailable in hardened/private browser modes.
70:     }
71:     applyTheme(newTheme);
72:   };
73: 
74:   if (!mounted) {
75:     return (
76:       <Button variant="outline" size="icon" aria-label="切换主题">
77:         <div className="w-5 h-5" />
78:       </Button>
79:     );
80:   }
81: 
82:   const currentOption = themeOptions.find(o => o.value === theme)!;
83:   const CurrentIcon = currentOption.icon;
84: 
85:   return (
86:     <DropdownMenu>
87:       <DropdownMenuTrigger
88:         className={cn(buttonVariants({ variant: "outline", size: "sm" }), "gap-0 px-2 sm:gap-2 sm:px-3")}
89:         title={`主题：${currentOption.label}`}
90:         aria-label="切换主题"
91:       >
92:         <CurrentIcon className="size-4" />
93:         <span className="hidden sm:inline">{currentOption.label}</span>
94:       </DropdownMenuTrigger>
95:       <DropdownMenuContent align="end" className="w-40">
96:         <DropdownMenuRadioGroup value={theme} onValueChange={selectTheme}>
97:           {themeOptions.map((option) => {
98:             const Icon = option.icon;
99:             return (
100:               <DropdownMenuRadioItem key={option.value} value={option.value}>
101:                 <Icon className="size-4" />
102:                 {option.label}
103:               </DropdownMenuRadioItem>
104:             );
105:           })}
106:         </DropdownMenuRadioGroup>
107:       </DropdownMenuContent>
108:     </DropdownMenu>
109:   );
110: }

