2: 
3: import { useEffect } from 'react';
4: import { CheckCircle, XCircle, X, Info } from 'lucide-react';
5: import { createPortal } from 'react-dom';
6: 
7: export interface ToastData {
8:   id: string;
9:   message: string;
10:   type: 'success' | 'error' | 'info';
11: }
12: 
13: export function Toast({
14:   toast,
15:   onDismiss,
16: }: {
17:   toast: ToastData;
18:   onDismiss: (id: string) => void;
19: }) {
20:   useEffect(() => {
21:     const timer = setTimeout(() => onDismiss(toast.id), 3000);
22:     return () => clearTimeout(timer);
23:   }, [toast.id, onDismiss]);
24: 
25:   const Icon = toast.type === 'success' ? CheckCircle : toast.type === 'info' ? Info : XCircle;
26:   const borderColor =
27:     toast.type === 'success' ? 'border-green-500/30'
28:       : toast.type === 'info' ? 'border-blue-500/30'
29:         : 'border-destructive/20';
30:   const textColor =
31:     toast.type === 'success' ? 'text-green-600'
32:       : toast.type === 'info' ? 'text-blue-600'
33:         : 'text-destructive';
34: 
35:   return createPortal(
36:     <div
37:       className={`fixed bottom-4 right-4 z-[10000] flex items-center gap-2 max-w-sm rounded-xl border ${borderColor} bg-card px-4 py-3 text-sm ${textColor} shadow-lg`}
38:     >
39:       <Icon className="w-4 h-4 flex-shrink-0" />
40:       <span className="flex-1">{toast.message}</span>
41:       <button
