1: 'use client';
2: 
3: import { useCallback, useEffect, useState } from 'react';
4: import { runtimeStorage } from '@/lib/runtime-storage';
5: 
6: export const WIDE_MODE_STORAGE_KEY = 'nova-wide-mode';
7: 
8: // 宽屏（侧栏）布局基于 xl 断点设计。视口窄于该宽度时，侧栏会与顶部 Header 重复、
9: // 纵向 Tab 布局错位，因此宽屏必须自动关闭；重新变宽不会自动开启。
10: export const WIDE_MODE_MIN_WIDTH = 1280;
11: 
12: type StoredWideMode = 'enabled' | 'disabled';
13: 
14: function readStoredWideMode(): boolean {
15:   if (typeof window === 'undefined') return false;
16: 
17:   try {
18:     return runtimeStorage.getItem(WIDE_MODE_STORAGE_KEY) === 'enabled';
19:   } catch {
20:     return false;
21:   }
22: }
23: 
24: function writeStoredWideMode(enabled: boolean): void {
25:   if (typeof window === 'undefined') return;
26: 
27:   try {
28:     const value: StoredWideMode = enabled ? 'enabled' : 'disabled';
29:     runtimeStorage.setItem(WIDE_MODE_STORAGE_KEY, value);
30:   } catch {
31:     // Storage can be unavailable in hardened/private browser modes.
32:   }
33: }
34: 
35: function viewportAllowsWide(): boolean {
36:   if (typeof window === 'undefined') return true;
37:   return window.innerWidth >= WIDE_MODE_MIN_WIDTH;
38: }
39: 
40: function dismissBootLoader(): void {
41:   const el = document.getElementById('app-boot-loader');
42:   if (el) el.remove();
43: }
44: 
45: /** 将宽度模式状态同步到 <html> 属性，确保 CSS 选择器始终有效 */
46: function syncHtmlAttribute(enabled: boolean): void {
47:   if (typeof document === 'undefined') return;
48:   if (enabled) {
49:     document.documentElement.setAttribute('data-wide-mode', '');
50:   } else {
51:     document.documentElement.removeAttribute('data-wide-mode');
52:   }
53: }
54: 
55: export function useWideMode() {
56:   // 初始渲染必须与静态导出 HTML 一致（wideMode=false），否则 wide-mode-init 内联脚本
57:   // 设置的 html[data-wide-mode] 会让客户端首屏读到 true，与构建期 HTML 不符而触发
58:   // React #418 文本水合错误。真实值在挂载后的 effect 中读取；期间由 #app-boot-loader 遮罩覆盖。
59:   const [wideMode, setWideModeState] = useState(false);
60:   const [mounted, setMounted] = useState(false);
61: 
62:   useEffect(() => {
63:     let cancelled = false;
64: 
65:     queueMicrotask(() => {
66:       if (cancelled) return;
67:       const stored = readStoredWideMode();
68:       const allowed = viewportAllowsWide();
69:       setWideModeState(stored && allowed);
70:       if (stored && !allowed) {
71:         // 在窄视口下加载时同样自动关闭，避免出现重复 Header 的坏状态。
72:         writeStoredWideMode(false);
73:       }
74:       setMounted(true);
75:       dismissBootLoader();
76:     });
77: 
78:     return () => {
79:       cancelled = true;
80:     };
81:   }, []);
82: 
83:   // 视口收窄到阈值以下时自动关闭宽屏；只做单向关闭，绝不自动开启。
84:   useEffect(() => {
85:     if (typeof window === 'undefined') return;
86: 
87:     const mql = window.matchMedia(`(max-width: ${WIDE_MODE_MIN_WIDTH - 1}px)`);
88: 
89:     const enforce = (isNarrow: boolean) => {
90:       if (!isNarrow) return;
91:       setWideModeState(current => {
92:         if (!current) return current;
93:         writeStoredWideMode(false);
94:         return false;
95:       });
96:     };
97: 
98:     enforce(mql.matches);
99:     const listener = (event: MediaQueryListEvent) => enforce(event.matches);
100:     mql.addEventListener('change', listener);
101: 
102:     return () => mql.removeEventListener('change', listener);
103:   }, []);
104: 
105:   // 将 wideMode 状态同步到 <html> 属性，使 CSS 选择器 html[data-wide-mode] 始终有效
106:   useEffect(() => {
107:     syncHtmlAttribute(wideMode);
108:   }, [wideMode]);
109: 
110:   const setWideMode = useCallback((enabled: boolean) => {
111:     if (enabled && !viewportAllowsWide()) return;
112:     setWideModeState(enabled);
113:     writeStoredWideMode(enabled);
114:   }, []);
115: 
116:   const toggleWideMode = useCallback(() => {
117:     setWideModeState(current => {
118:       const next = !current;
119:       if (next && !viewportAllowsWide()) return current;
120:       writeStoredWideMode(next);
121:       return next;
122:     });
123:   }, [])

