2: // 此前 job-store 与 image-downloader 各自在每次读写时都 indexedDB.open()+close()
3: // （一个任务 N 张图就开关 N 次），且部分打开点缺少 onupgradeneeded，在全新库上
4: // 先执行会建出「没有对象存储」的库，导致后续 transaction 抛 "object store not found"。
5: // 这里统一为单例缓存连接 + 统一升级逻辑，消除两个问题。
6: 
7: export const DB_NAME = 'nova-image-db';
8: export const DB_VERSION = 2;
9: export const IMG_STORE = 'images';
10: export const BLOBS_STORE = 'blobs';
11: 
12: let dbPromise: Promise<IDBDatabase | null> | null = null;
13: 
14: export function openImageDb(): Promise<IDBDatabase | null> {
15:   if (typeof indexedDB === 'undefined') return Promise.resolve(null);
16:   if (dbPromise) return dbPromise;
17: 
18:   dbPromise = new Promise<IDBDatabase | null>((resolve) => {
19:     const req = indexedDB.open(DB_NAME, DB_VERSION);
20:     req.onerror = () => { dbPromise = null; resolve(null); };
21:     req.onupgradeneeded = (e) => {
22:       const db = (e.target as IDBOpenDBRequest).result;
23:       if (!db.objectStoreNames.contains(IMG_STORE)) {
24:         db.createObjectStore(IMG_STORE, { keyPath: 'id' });
25:       }
26:       if (!db.objectStoreNames.contains(BLOBS_STORE)) {
27:         db.createObjectStore(BLOBS_STORE, { keyPath: 'key' });
28:       }
29:     };
30:     req.onsuccess = () => {
31:       const db = req.result;
32:       // 另一个 tab 触发升级时主动关闭并失效缓存，下次调用会重新打开。
33:       db.onversionchange = () => { try { db.close(); } catch { /* ignore */ } dbPromise = null; };
34:       db.onclose = () => { dbPromise = null; };
35:       resolve(db);
36:     };
37:   });
38:   return dbPromise;
39: }

