// Dependency-free before/after UI benchmark for nova-image-studio.
// Serves static Next.js exports, drives Playwright's cached Chromium over raw CDP,
// captures screenshots and scroll frame timings. Lives outside the repo on purpose.
import http from 'node:http';
import fs from 'node:fs';
import fsp from 'node:fs/promises';
import path from 'node:path';
import { spawn } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { setTimeout as sleep } from 'node:timers/promises';

const BENCH_DIR = path.dirname(fileURLToPath(import.meta.url));
const CHROME = path.join(process.env.LOCALAPPDATA, 'ms-playwright', 'chromium-1228', 'chrome-win64', 'chrome.exe');

// ---------- args ----------
const argv = Object.fromEntries(process.argv.slice(2).map(a => {
  const [k, ...v] = a.replace(/^--/, '').split('=');
  return [k, v.length ? v.join('=') : true];
}));
const targets = String(argv.targets || '').split(',').filter(Boolean).map((pair, i) => {
  const [name, dir] = pair.split('@');
  return { name, root: path.resolve(dir), port: 47810 + i };
});
if (!targets.length) throw new Error('usage: node bench.mjs --targets=name@dir[,name@dir] [--scenarios=a,b] [--repeat=3] [--no-shots] [--no-perf]');
const REPEAT = Number(argv.repeat || 3);
const SHOTS = !argv['no-shots'];
const PERF = !argv['no-perf'];
const PERF_DPR = Number(argv.dpr || 1.5);
const SCROLL_MS = Number(argv.scrollMs || 6000);

// ---------- static server ----------
const MIME = {
  '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.css': 'text/css; charset=utf-8',
  '.json': 'application/json', '.png': 'image/png', '.webp': 'image/webp', '.svg': 'image/svg+xml',
  '.ico': 'image/x-icon', '.woff2': 'font/woff2', '.woff': 'font/woff', '.txt': 'text/plain; charset=utf-8',
  '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.map': 'application/json', '.webmanifest': 'application/manifest+json',
};
function startServer(root, port) {
  const server = http.createServer(async (req, res) => {
    try {
      const url = new URL(req.url, 'http://127.0.0.1');
      let p = decodeURIComponent(url.pathname);
      if (p.startsWith('/api/')) { res.writeHead(404, { 'content-type': 'application/json' }); res.end('{"error":"bench-static"}'); return; }
      if (p.endsWith('/')) p += 'index.html';
      let file = path.normalize(path.join(root, p));
      if (file !== root && !file.startsWith(root + path.sep)) { res.writeHead(403); res.end(); return; }
      let stat = await fsp.stat(file).catch(() => null);
      if (stat?.isDirectory()) { file = path.join(file, 'index.html'); stat = await fsp.stat(file).catch(() => null); }
      if (!stat) { const alt = `${file}.html`; stat = await fsp.stat(alt).catch(() => null); if (stat) file = alt; }
      if (!stat) { res.writeHead(404); res.end('not found'); return; }
      res.writeHead(200, { 'content-type': MIME[path.extname(file).toLowerCase()] || 'application/octet-stream', 'cache-control': 'no-store' });
      fs.createReadStream(file).pipe(res);
    } catch (error) { res.writeHead(500); res.end(String(error)); }
  });
  server.on('upgrade', (_req, socket) => socket.destroy());
  return new Promise(resolve => server.listen(port, '127.0.0.1', () => resolve(server)));
}

// ---------- CDP ----------
class CDP {
  constructor(ws) {
    this.ws = ws; this.id = 0; this.pending = new Map(); this.listeners = new Set();
    ws.addEventListener('message', event => {
      const msg = JSON.parse(typeof event.data === 'string' ? event.data : Buffer.from(event.data).toString());
      if (msg.id && this.pending.has(msg.id)) {
        const { resolve, reject, timer } = this.pending.get(msg.id);
        clearTimeout(timer); this.pending.delete(msg.id);
        if (msg.error) reject(new Error(`${msg.error.message} ${msg.error.data || ''}`)); else resolve(msg.result);
      } else if (msg.method) {
        for (const listener of this.listeners) listener(msg);
      }
    });
  }
  static connect(url) {
    return new Promise((resolve, reject) => {
      const ws = new WebSocket(url);
      ws.addEventListener('open', () => resolve(new CDP(ws)), { once: true });
      ws.addEventListener('error', () => reject(new Error(`websocket error ${url}`)), { once: true });
    });
  }
  send(method, params = {}, sessionId) {
    const id = ++this.id;
    const msg = { id, method, params };
    if (sessionId) msg.sessionId = sessionId;
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => { this.pending.delete(id); reject(new Error(`timeout ${method}`)); }, 90000);
      this.pending.set(id, { resolve, reject, timer });
      this.ws.send(JSON.stringify(msg));
    });
  }
  on(listener) { this.listeners.add(listener); return () => this.listeners.delete(listener); }
}

class Page {
  constructor(cdp, sessionId, targetId) { this.cdp = cdp; this.sessionId = sessionId; this.targetId = targetId; this.errors = []; }
  send(method, params) { return this.cdp.send(method, params, this.sessionId); }
  async eval(expression) {
    const r = await this.send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
    if (r.exceptionDetails) throw new Error(`eval failed: ${r.exceptionDetails.exception?.description || r.exceptionDetails.text}`);
    return r.result.value;
  }
  async waitFor(expression, timeout = 15000) {
    const t0 = Date.now();
    while (Date.now() - t0 < timeout) {
      try { if (await this.eval(expression)) return true; } catch { /* retry */ }
      await sleep(100);
    }
    return false;
  }
  waitEvent(method, timeout = 30000) {
    return new Promise(resolve => {
      const off = this.cdp.on(msg => {
        if (msg.method === method && msg.sessionId === this.sessionId) { off(); resolve(msg.params); }
      });
      setTimeout(() => { off(); resolve(null); }, timeout);
    });
  }
  async navigate(url) {
    const loaded = this.waitEvent('Page.loadEventFired');
    await this.send('Page.navigate', { url });
    await loaded;
  }
  async reload() {
    const loaded = this.waitEvent('Page.loadEventFired');
    await this.send('Page.reload', { ignoreCache: true });
    await loaded;
  }
  async rectOf(expr) {
    return this.eval(`(() => { const el = (${expr}); if (!el) return null; const r = el.getBoundingClientRect(); return { x: r.left, y: r.top, width: r.width, height: r.height }; })()`);
  }
  async mouseMove(x, y) { await this.send('Input.dispatchMouseEvent', { type: 'mouseMoved', x, y }); }
  async click(expr) {
    const r = await this.rectOf(expr);
    if (!r) throw new Error(`click target not found: ${expr}`);
    const x = r.x + r.width / 2; const y = r.y + r.height / 2;
    await this.mouseMove(x, y);
    await this.send('Input.dispatchMouseEvent', { type: 'mousePressed', x, y, button: 'left', clickCount: 1 });
    await this.send('Input.dispatchMouseEvent', { type: 'mouseReleased', x, y, button: 'left', clickCount: 1 });
  }
  async key(key) {
    await this.send('Input.dispatchKeyEvent', { type: 'keyDown', key, code: key, windowsVirtualKeyCode: key === 'Escape' ? 27 : 0 });
    await this.send('Input.dispatchKeyEvent', { type: 'keyUp', key, code: key, windowsVirtualKeyCode: key === 'Escape' ? 27 : 0 });
  }
  async screenshot(file, clip) {
    const params = { format: 'png' };
    if (clip) params.clip = { x: Math.max(0, clip.x), y: Math.max(0, clip.y), width: clip.width, height: clip.height, scale: 1 };
    const r = await this.send('Page.captureScreenshot', params);
    await fsp.mkdir(path.dirname(file), { recursive: true });
    await fsp.writeFile(file, Buffer.from(r.data, 'base64'));
  }
}

async function launchChrome(port, userDataDir) {
  const args = [
    '--headless=new', `--remote-debugging-port=${port}`, `--user-data-dir=${userDataDir}`,
    '--no-first-run', '--no-default-browser-check', '--disable-extensions', '--disable-background-networking',
    '--disable-component-update', '--disable-sync', '--disable-default-apps', '--mute-audio',
    '--window-size=1440,920', '--ignore-gpu-blocklist', '--enable-gpu-rasterization',
    '--disable-gpu-vsync', '--disable-frame-rate-limit', ...(argv.angle ? [`--use-angle=${argv.angle}`] : []),
    'about:blank',
  ];
  const proc = spawn(CHROME, args, { stdio: 'ignore' });
  for (let i = 0; i < 150; i++) {
    try {
      const r = await fetch(`http://127.0.0.1:${port}/json/version`);
      if (r.ok) return { proc, info: await r.json() };
    } catch { /* not ready */ }
    await sleep(100);
  }
  proc.kill();
  throw new Error('chrome did not start');
}

// ---------- in-page scripts ----------
const DESKTOP_BRIDGE_JS = `
  const readIdb = () => new Promise(resolve => {
    const req = indexedDB.open('nova-image-db', 2);
    req.onupgradeneeded = () => { const d = req.result; if (!d.objectStoreNames.contains('images')) d.createObjectStore('images', { keyPath: 'id' }); if (!d.objectStoreNames.contains('blobs')) d.createObjectStore('blobs', { keyPath: 'key' }); };
    req.onsuccess = () => { const db = req.result; const g = db.transaction('images', 'readonly').objectStore('images').getAll(); g.onsuccess = () => { resolve(g.result || []); db.close(); }; g.onerror = () => { resolve([]); db.close(); }; };
    req.onerror = () => resolve([]);
  });
  const list = async ns => ns === 'image-records' ? (await readIdb()).map(v => ({ key: v.id, value: v, createdAt: '', updatedAt: '' })) : [];
  const s3cfg = { endpoint: '', region: '', bucket: '', rootPrefix: '', forcePathStyle: false, hasAccessKeyId: false, hasSecretAccessKey: false, hasSessionToken: false };
  window.novaDesktop = {
    platform: 'win32',
    config: { get: k => localStorage.getItem(k), set: (k, v) => localStorage.setItem(k, v), remove: k => localStorage.removeItem(k) },
    records: { get: async (ns, key) => (await list(ns)).find(e => e.key === key)?.value ?? null, list, put: async () => {}, delete: async () => {}, clear: async () => {} },
    files: { read: async () => null, list: async () => [], write: async (ns, id, data, mimeType) => ({ id, namespace: ns, mimeType, sizeBytes: data?.length || 0, sha256: '' }), delete: async () => {} },
    s3: { getConfig: async () => s3cfg, saveConfig: async () => s3cfg, clearCredentials: async () => s3cfg, testConnection: async () => ({ available: false, message: 'bench' }), listFolder: async () => ({ prefix: '', folders: [], objects: [] }), readThumbnail: async () => null, readObject: async () => null, uploadObject: async () => null, createFolder: async () => null, downloadObject: async () => ({ canceled: true }) },
    backup: { export: async () => ({ canceled: true }), import: async () => ({ canceled: true }) },
    updater: { check: async () => ({ state: 'disabled' }), getStatus: async () => ({ state: 'disabled' }), restartAndInstall: async () => ({ installed: false }), onStatus: () => () => {} },
    openDataDirectory: async () => '',
  };
`;
const initScript = ({ desktop, wide, theme }) => `(() => {
  try { localStorage.setItem('theme', ${JSON.stringify(theme)}); localStorage.setItem('nova-wide-mode', ${JSON.stringify(wide ? 'enabled' : 'disabled')}); } catch {}
  ${desktop ? DESKTOP_BRIDGE_JS : ''}
})();`;

const SEED_JS = `(async () => {
  const W = 400, H = 300;
  const palettes = [['#0f766e','#99f6e4','#fef3c7'],['#1e3a8a','#93c5fd','#fde68a'],['#7c2d12','#fdba74','#fef9c3'],['#14532d','#86efac','#e0f2fe'],['#581c87','#f0abfc','#fce7f3'],['#0c4a6e','#7dd3fc','#ecfeff'],['#365314','#bef264','#fefce8'],['#831843','#f9a8d4','#fff1f2'],['#134e4a','#5eead4','#f0fdfa'],['#1f2937','#9ca3af','#f9fafb'],['#78350f','#fcd34d','#fffbeb'],['#064e3b','#6ee7b7','#ecfdf5']];
  const canvas = document.createElement('canvas'); canvas.width = W; canvas.height = H; const ctx = canvas.getContext('2d');
  const images = palettes.map((p, i) => {
    const g = ctx.createLinearGradient(0, 0, W, H); g.addColorStop(0, p[0]); g.addColorStop(0.6, p[1]); g.addColorStop(1, p[2]);
    ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
    for (let k = 0; k < 6; k++) { ctx.beginPath(); ctx.fillStyle = 'rgba(255,255,255,' + (0.08 + k * 0.03) + ')'; ctx.arc((i * 37 + k * 71) % W, (i * 53 + k * 41) % H, 30 + k * 14, 0, Math.PI * 2); ctx.fill(); }
    ctx.fillStyle = 'rgba(0,0,0,0.18)'; ctx.fillRect(0, H * 0.72, W, H * 0.28);
    return canvas.toDataURL('image/png').split(',')[1];
  });
  const prompts = ['晨雾中的竹林小径，电影感光影，35mm 胶片质感', 'A cozy reading nook by a rainy window, warm tungsten light, ultra detailed', '赛博朋克风格的夜市街景，霓虹灯倒影，湿润路面', 'Minimalist product shot of a ceramic teapot on travertine, soft shadows', '水彩风格的江南古镇，小桥流水，淡雅色调', 'Isometric illustration of a tiny greenhouse full of succulents', '雪山湖泊日出，高饱和，广角镜头', 'Portrait of an astronaut gardener, pastel palette, studio lighting'];
  const jobs = []; const records = []; const now = Date.now();
  for (let i = 0; i < 80; i++) {
    const day = Math.floor(i / 8);
    const created = new Date(now - day * 86400000 - (i % 8) * 1800000).toISOString();
    const mode = i % 3 === 0 ? 'image-to-image' : 'text-to-image';
    const count = i % 4 === 0 ? 2 : 1; const failed = i % 13 === 7;
    const id = 'bench-' + String(i).padStart(3, '0');
    const job = { id, status: failed ? 'failed' : 'completed', mode, prompt: prompts[i % prompts.length], output_size: '1K', temperature: 1, aspect_ratio: '4:3', model: 'gemini-3-pro-image-preview', created_at: created, parallelCount: count };
    if (failed) { job.terminal = true; job.error = '模拟失败：上游返回 429 Too Many Requests'; }
    jobs.push(job);
    const imgs = failed ? undefined : Array.from({ length: count }, (_, k) => images[(i + k) % images.length]);
    records.push({ id, jobId: id, status: job.status, imageData: imgs?.[0], images: imgs, refImages: mode === 'image-to-image' ? [{ id: id + '-ref', name: 'reference.png', dataUrl: 'data:image/png;base64,' + images[(i + 5) % images.length], mimeType: 'image/png' }] : undefined, error: job.error });
  }
  localStorage.setItem('nova-jobs', JSON.stringify(jobs));
  const db = await new Promise((resolve, reject) => { const req = indexedDB.open('nova-image-db', 2); req.onupgradeneeded = () => { const d = req.result; if (!d.objectStoreNames.contains('images')) d.createObjectStore('images', { keyPath: 'id' }); if (!d.objectStoreNames.contains('blobs')) d.createObjectStore('blobs', { keyPath: 'key' }); }; req.onsuccess = () => resolve(req.result); req.onerror = () => reject(req.error); });
  await new Promise((resolve, reject) => { const tx = db.transaction('images', 'readwrite'); const store = tx.objectStore('images'); for (const r of records) store.put(r); tx.oncomplete = resolve; tx.onerror = () => reject(tx.error); });
  db.close();
  return jobs.length;
})()`;

const COUNT_JS = `(() => {
  let total = 0, inView = 0; const vw = innerWidth, vh = innerHeight; const all = document.querySelectorAll('*');
  for (const el of all) {
    const cs = getComputedStyle(el); const bf = cs.backdropFilter || cs.webkitBackdropFilter;
    if (bf && bf !== 'none') { total++; const r = el.getBoundingClientRect(); if (r.width > 0 && r.height > 0 && r.bottom > 0 && r.right > 0 && r.top < vh && r.left < vw) inView++; }
  }
  const probe = document.createElement('code'); probe.className = 'font-mono'; document.body.appendChild(probe);
  const mono = getComputedStyle(probe).fontFamily; probe.remove();
  return { backdropTotal: total, backdropInView: inView, domNodes: all.length, bodyFont: getComputedStyle(document.body).fontFamily, monoFont: mono };
})()`;

const perfJs = (targetExpr, durationMs) => `(async () => {
  const scroller = (${targetExpr});
  if (!scroller) return { skipped: 'no-target' };
  const max = scroller.scrollHeight - scroller.clientHeight;
  if (max < 200) return { skipped: 'not-scrollable', max };
  scroller.scrollTop = 0;
  await new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r)));
  const deltas = []; let longTasks = 0; let start = null; let last = null;
  const po = new PerformanceObserver(list => { longTasks += list.getEntries().length; });
  try { po.observe({ type: 'longtask' }); } catch {}
  await new Promise(resolve => {
    const step = t => {
      if (start === null) { start = t; last = t; }
      else { deltas.push(t - last); last = t; }
      const elapsed = t - start;
      scroller.scrollTop = max * (1 - Math.cos((elapsed / ${durationMs}) * Math.PI * 2)) / 2;
      if (elapsed < ${durationMs}) requestAnimationFrame(step); else resolve();
    };
    requestAnimationFrame(step);
  });
  po.disconnect();
  const sorted = [...deltas].sort((a, b) => a - b);
  const pct = p => sorted[Math.min(sorted.length - 1, Math.floor(p * sorted.length))];
  const avg = deltas.reduce((a, b) => a + b, 0) / deltas.length;
  return { frames: deltas.length, avgMs: +avg.toFixed(2), p50Ms: +pct(0.5).toFixed(2), p95Ms: +pct(0.95).toFixed(2), p99Ms: +pct(0.99).toFixed(2), maxMs: +sorted[sorted.length - 1].toFixed(2), over17: deltas.filter(d => d > 17.5).length, longTasks, scrollRange: max };
})()`;

const HISTORY_SCROLLER = `document.querySelector('.studio-history-list')`;
const WINDOW_SCROLLER = `document.scrollingElement`;
const SETTINGS_SCROLLER = `(() => { const root = document.querySelector('.nova-app-settings'); if (!root) return null; let best = null, bestRange = 0; for (const el of root.querySelectorAll('*')) { const cs = getComputedStyle(el); if (!/(auto|scroll)/.test(cs.overflowY)) continue; const range = el.scrollHeight - el.clientHeight; if (range > bestRange) { best = el; bestRange = range; } } return best; })()`;

const SCENARIOS = {
  'web-agent-light': { desktop: false, wide: false, theme: 'light', tab: null },
  'web-gen-light': { desktop: false, wide: false, theme: 'light', tab: '生图工作台', perf: { window: WINDOW_SCROLLER, history: HISTORY_SCROLLER } },
  'web-wide-gen-light': { desktop: false, wide: true, theme: 'light', tab: '生图工作台', hover: true, dropdown: true, perf: { history: HISTORY_SCROLLER } },
  'web-wide-gen-dark': { desktop: false, wide: true, theme: 'dark', tab: '生图工作台', hover: true, perf: { history: HISTORY_SCROLLER } },
  'desktop-wide-gen-light': { desktop: true, wide: true, theme: 'light', tab: '生图工作台', settings: true, perf: { history: HISTORY_SCROLLER } },
  'desktop-agent-dark': { desktop: true, wide: true, theme: 'dark', tab: null },
  'desktop-normal-gen-dark': { desktop: true, wide: false, theme: 'dark', tab: '生图工作台' },
};
const scenarioNames = argv.scenarios ? String(argv.scenarios).split(',') : Object.keys(SCENARIOS);

// ---------- runner ----------
async function openPage(cdp, scenario) {
  const { targetId } = await cdp.send('Target.createTarget', { url: 'about:blank' });
  const { sessionId } = await cdp.send('Target.attachToTarget', { targetId, flatten: true });
  const page = new Page(cdp, sessionId, targetId);
  cdp.on(msg => {
    if (msg.sessionId !== sessionId) return;
    if (msg.method === 'Runtime.exceptionThrown') page.errors.push(`exception: ${msg.params.exceptionDetails?.exception?.description?.split('\n')[0] || msg.params.exceptionDetails?.text}`);
    if (msg.method === 'Runtime.consoleAPICalled' && msg.params.type === 'error') {
      const text = msg.params.args.map(a => a.value ?? a.description ?? '').join(' ');
      if (!/Failed to load resource|WebSocket connection|bench-static|404/.test(text)) page.errors.push(`console: ${text.slice(0, 240)}`);
    }
  });
  await page.send('Page.enable');
  await page.send('Runtime.enable');
  await page.send('Performance.enable');
  await page.send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 920, deviceScaleFactor: 1, mobile: false });
  await page.send('Emulation.setEmulatedMedia', { features: [{ name: 'prefers-color-scheme', value: scenario?.theme || 'light' }] });
  if (scenario) await page.send('Page.addScriptToEvaluateOnNewDocument', { source: initScript(scenario) });
  return page;
}

async function waitReady(page) {
  await page.waitFor(`document.readyState === 'complete' && !document.getElementById('app-boot-loader')`, 20000);
  await page.waitFor(`[...document.images].every(i => i.complete)`, 10000);
  await sleep(700);
}

async function metricsSnapshot(page) {
  const { metrics } = await page.send('Performance.getMetrics');
  return Object.fromEntries(metrics.map(m => [m.name, m.value]));
}

async function runScenario(cdp, target, name, { shots, perf }) {
  const scenario = SCENARIOS[name];
  const base = `http://127.0.0.1:${target.port}/`;
  const page = await openPage(cdp, scenario);
  const result = { target: target.name, scenario: name };
  try {
    await page.navigate(base);
    await waitReady(page);
    if (scenario.tab) {
      await page.click(`[...document.querySelectorAll('[role="tab"]')].find(t => t.textContent.includes(${JSON.stringify(scenario.tab)}))`);
      await sleep(400);
      await page.waitFor(`[...document.images].every(i => i.complete)`, 10000);
      await sleep(700);
    }
    result.structure = await page.eval(COUNT_JS);
    const shotDir = path.join(BENCH_DIR, 'shots', target.name);
    if (shots) {
      await page.mouseMove(2, 2);
      await sleep(150);
      await page.screenshot(path.join(shotDir, `${name}.png`));
      if (scenario.hover) {
        const media = await page.rectOf(`document.querySelector('.studio-result-media')`);
        const card = await page.rectOf(`document.querySelector('.studio-result-card')`);
        if (media && card) {
          await page.mouseMove(media.x + media.width / 2, media.y + media.height / 2);
          await sleep(400);
          await page.screenshot(path.join(shotDir, `${name}--hover.png`), { x: card.x - 12, y: card.y - 12, width: card.width + 24, height: card.height + 24 });
          await page.mouseMove(2, 2);
        }
      }
      if (scenario.dropdown) {
        try {
          await page.click(`document.querySelector('[title="随机图片"]')`);
          await sleep(450);
          const menu = await page.rectOf(`document.querySelector('[data-slot="dropdown-menu-content"]')`);
          const trigger = await page.rectOf(`document.querySelector('[title="随机图片"]')`);
          if (menu && trigger) {
            const x = Math.min(menu.x, trigger.x) - 24; const y = Math.min(menu.y, trigger.y) - 24;
            const right = Math.max(menu.x + menu.width, trigger.x + trigger.width) + 24; const bottom = Math.max(menu.y + menu.height, trigger.y + trigger.height) + 24;
            await page.screenshot(path.join(shotDir, `${name}--dropdown.png`), { x, y, width: right - x, height: bottom - y });
          }
          await page.key('Escape');
          await sleep(300);
        } catch (error) { result.dropdownError = String(error.message || error); }
      }
    }
    if (scenario.settings) {
      try {
        await page.click(`[...document.querySelectorAll('button')].find(b => b.textContent.trim() === '设置' || b.title === '设置' || b.getAttribute('aria-label') === '设置')`);
        await page.waitFor(`!!document.querySelector('.nova-app-settings')`, 5000);
        await sleep(600);
        if (shots) await page.screenshot(path.join(shotDir, `${name}--settings.png`));
        result.settingsStructure = await page.eval(COUNT_JS);
        if (perf) {
          await page.send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 920, deviceScaleFactor: PERF_DPR, mobile: false });
          await sleep(500);
          const m0 = await metricsSnapshot(page);
          result.perfSettings = await page.eval(perfJs(SETTINGS_SCROLLER, SCROLL_MS));
          const m1 = await metricsSnapshot(page);
          result.perfSettings.cpu = cpuDelta(m0, m1);
          await page.send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 920, deviceScaleFactor: 1, mobile: false });
        }
        await page.key('Escape');
        await sleep(400);
      } catch (error) { result.settingsError = String(error.message || error); }
    }
    if (perf && scenario.perf) {
      await page.send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 920, deviceScaleFactor: PERF_DPR, mobile: false });
      await sleep(600);
      result.perf = {};
      for (const [key, expr] of Object.entries(scenario.perf)) {
        const m0 = await metricsSnapshot(page);
        const r = await page.eval(perfJs(expr, SCROLL_MS));
        const m1 = await metricsSnapshot(page);
        r.cpu = cpuDelta(m0, m1);
        result.perf[key] = r;
        await sleep(300);
      }
    }
  } catch (error) {
    result.error = String(error.stack || error);
  } finally {
    result.errors = page.errors.slice(0, 12);
    await cdp.send('Target.closeTarget', { targetId: page.targetId }).catch(() => {});
  }
  return result;
}

function cpuDelta(a, b) {
  const d = k => +(((b[k] || 0) - (a[k] || 0)) * 1000).toFixed(1);
  return { taskMs: d('TaskDuration'), scriptMs: d('ScriptDuration'), layoutMs: d('LayoutDuration'), styleMs: d('RecalcStyleDuration') };
}

async function seedTarget(cdp, target) {
  const page = await openPage(cdp, null);
  try {
    await page.navigate(`http://127.0.0.1:${target.port}/`);
    await waitReady(page);
    const n = await page.eval(SEED_JS);
    return n;
  } finally {
    await cdp.send('Target.closeTarget', { targetId: page.targetId }).catch(() => {});
  }
}

async function cssBytes(root) {
  let total = 0;
  async function walk(dir) {
    for (const entry of await fsp.readdir(dir, { withFileTypes: true })) {
      const p = path.join(dir, entry.name);
      if (entry.isDirectory()) await walk(p); else if (entry.name.endsWith('.css')) total += (await fsp.stat(p)).size;
    }
  }
  await walk(path.join(root, '_next', 'static')).catch(() => {});
  return total;
}

const median = values => { const s = values.filter(v => typeof v === 'number').sort((a, b) => a - b); return s.length ? s[Math.floor(s.length / 2)] : null; };

async function main() {
  const servers = await Promise.all(targets.map(t => startServer(t.root, t.port)));
  const userDataDir = path.join(BENCH_DIR, `profile-${Date.now()}`);
  const { proc, info } = await launchChrome(47900, userDataDir);
  const cdp = await CDP.connect(info.webSocketDebuggerUrl);
  const report = { browser: info.Browser, when: new Date().toISOString(), perfDpr: PERF_DPR, scrollMs: SCROLL_MS, targets: {}, runs: [] };
  try {
    const sys = await cdp.send('SystemInfo.getInfo').catch(() => null);
    report.gpu = sys ? { device: sys.gpu?.devices?.map(d => d.deviceString).join(' | '), gpuCompositing: sys.gpu?.featureStatus?.gpu_compositing, rasterization: sys.gpu?.featureStatus?.rasterization } : null;
    console.log('browser', info.Browser, JSON.stringify(report.gpu));
    for (const target of targets) {
      report.targets[target.name] = { root: target.root, cssBytes: await cssBytes(target.root), seeded: await seedTarget(cdp, target) };
    }
    for (let rep = 0; rep < (PERF ? REPEAT : 1); rep++) {
      for (const name of scenarioNames) {
        for (const target of rep % 2 === 0 ? targets : [...targets].reverse()) {
          const r = await runScenario(cdp, target, name, { shots: SHOTS && rep === 0, perf: PERF });
          r.rep = rep;
          report.runs.push(r);
          const perfLine = r.perf ? Object.entries(r.perf).map(([k, v]) => `${k}: ${v.skipped ? v.skipped : `avg ${v.avgMs}ms p95 ${v.p95Ms}ms >17ms ${v.over17}/${v.frames}`}`).join(' | ') : '';
          console.log(`[${rep}] ${target.name.padEnd(9)} ${name.padEnd(24)} backdrop ${r.structure?.backdropInView ?? '?'}/${r.structure?.backdropTotal ?? '?'} ${perfLine}${r.perfSettings ? ` | settings: ${r.perfSettings.skipped || `avg ${r.perfSettings.avgMs}ms p95 ${r.perfSettings.p95Ms}ms`}` : ''}${r.error ? ` ERROR ${r.error.split('\n')[0]}` : ''}${r.errors?.length ? ` errors=${r.errors.length}` : ''}`);
        }
      }
    }
    // medians per target/scenario/metric
    const summary = {};
    for (const r of report.runs) {
      const key = `${r.scenario}`;
      summary[key] ??= {};
      summary[key][r.target] ??= { backdropInView: r.structure?.backdropInView, backdropTotal: r.structure?.backdropTotal, bodyFont: r.structure?.bodyFont, monoFont: r.structure?.monoFont, perf: {} };
      const bucket = summary[key][r.target].perf;
      for (const [k, v] of Object.entries(r.perf || {})) { if (v.skipped) continue; (bucket[k] ??= []).push(v); }
      if (r.perfSettings && !r.perfSettings.skipped) (bucket.settings ??= []).push(r.perfSettings);
    }
    for (const scen of Object.values(summary)) for (const t of Object.values(scen)) for (const [k, list] of Object.entries(t.perf)) {
      t.perf[k] = { n: list.length, avgMs: median(list.map(v => v.avgMs)), p95Ms: median(list.map(v => v.p95Ms)), p99Ms: median(list.map(v => v.p99Ms)), over17Pct: median(list.map(v => +(100 * v.over17 / v.frames).toFixed(1))), taskMs: median(list.map(v => v.cpu.taskMs)), styleMs: median(list.map(v => v.cpu.styleMs)), layoutMs: median(list.map(v => v.cpu.layoutMs)) };
    }
    report.summary = summary;
    const out = path.join(BENCH_DIR, `report-${targets.map(t => t.name).join('-')}.json`);
    await fsp.writeFile(out, JSON.stringify(report, null, 2));
    console.log('SUMMARY', JSON.stringify(summary, null, 1));
    console.log('CSS', JSON.stringify(Object.fromEntries(Object.entries(report.targets).map(([k, v]) => [k, v.cssBytes]))));
    console.log('report ->', out);
  } finally {
    try { await cdp.send('Browser.close'); } catch { proc.kill(); }
    await sleep(500);
    servers.forEach(s => s.close());
    await fsp.rm(userDataDir, { recursive: true, force: true }).catch(() => {});
  }
}

main().catch(error => { console.error(error); process.exit(1); });

