+// Dependency-free before/after UI benchmark for nova-image-studio.
+// Serves static Next.js exports, drives Playwright's cached Chromium over raw CDP,
+// captures screenshots and scroll frame timings. Lives outside the repo on purpose.
+import http from 'node:http';
+import fs from 'node:fs';
+import fsp from 'node:fs/promises';
+import path from 'node:path';
+import { spawn } from 'node:child_process';
+import { fileURLToPath } from 'node:url';
