+      report.targets[target.name] = { root: target.root, cssBytes: await cssBytes(target.root), seeded: await seedTarget(cdp, target) };
+    }
+    for (let rep = 0; rep < (PERF ? REPEAT : 1); rep++) {
+      for (const name of scenarioNames) {
+        for (const target of rep % 2 === 0 ? targets : [...targets].reverse()) {
+          const r = await runScenario(cdp, target, name, { shots: SHOTS && rep === 0, perf: PERF });
+          r.rep = rep;
+          report.runs.push(r);
+          const perfLine = r.perf ? Object.entries(r.perf).map(([k, v]) => `${k}: ${v.skipped ? v.skipped : `avg ${v.avgMs}ms p95 ${v.p95Ms}ms >17ms ${v.over17}/${v.frames}`}`).join(' | ') : '';
+          console.log(`[${rep}] ${target.name.padEnd(9)} ${name.padEnd(24)} backdrop ${r.structure?.backdropInView ?? '?'}/${r.structure?.backdropTotal ?? '?'} ${perfLine}${r.perfSettings ? ` | settings: ${r.perfSettings.skipped || `avg ${r.perfSettings.avgMs}ms p95 ${r.perfSettings.p95Ms}ms`}` : ''}${r.error ? ` ERROR ${r.error.split('\n')[0]}` : ''}${r.errors?.length ? ` errors=${r.errors.length}` : ''}`);
+        }
+      }
+    }
+    // medians per target/scenario/metric
+    const summary = {};
+    for (const r of report.runs) {
+      const key = `${r.scenario}`;
+      summary[key] ??= {};
+      summary[key][r.target] ??= { backdropInView: r.structure?.backdropInView, backdropTotal: r.structure?.backdropTotal, bodyFont: r.structure?.bodyFont, monoFont: r.structure?.monoFont, perf: {} };
+      const bucket = summary[key][r.target].perf;
+      for (const [k, v] of Object.entries(r.perf || {})) { if (v.skipped) continue; (bucket[k] ??= []).push(v); }
+      if (r.perfSettings && !r.perfSettings.skipped) (bucket.settings ??= []).push(r.perfSettings);
+    }
+    for (const scen of Object.values(summary)) for (const t of Object.values(scen)) for (const [k, list] of Object.entries(t.perf)) {
+      t.perf[k] = { n: list.length, avgMs: median(list.map(v => v.avgMs)), p95Ms: median(list.map(v => v.p95Ms)), p99Ms: median(list.map(v => v.p99Ms)), over17Pct: median(list.map(v => +(100 * v.over17 / v.frames).toFixed(1))), taskMs: median(list.map(v => v.cpu.taskMs)), styleMs: median(list.map(v => v.cpu.styleMs)), layoutMs: median(list.map(v => v.cpu.layoutMs)) };
+    }
+    report.summary = summary;
+    const out = path.join(BENCH_DIR, `report-${targets.map(t => t.name).join('-')}.json`);
+    await fsp.writeFile(out, JSON.stringify(report, null, 2));
+    console.log('SUMMARY', JSON.stringify(summary, null, 1));
+    console.log('CSS', JSON.stringify(Object.fromEntries(Object.entries(report.targets).map(([k, v]) => [k, v.cssBytes]))));
+    console.log('report ->', out);
+  } finally {
+    try { await cdp.send('Browser.close'); } catch { proc.kill(); }
+    await sleep(500);
+    servers.forEach(s => s.close());
+    await fsp.rm(userDataDir, { recursive: true, force: true }).catch(() => {});
+  }
+}
+
+main().catch(error => { console.error(error); process.exit(1); });

