html,
body {
  overflow-x: hidden;
  overscroll-behavior-x: none;
}

/* Wide mode: 所有内部功能已有滚动条，禁止外层滚动 */
html[data-wide-mode] {
  overflow: hidden;
}

body {
  font-family: var(--nova-font-sans);
  background-color: var(--background);
  transition: background-color 0.2s ease, color 0.2s ease;
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }

  html {
    font-family: var(--nova-font-sans);
    -webkit-tap-highlight-color: transparent;
  }

  body {
    @apply bg-background text-foreground;
  }

  ::selection {
    background-color: color-mix(in srgb, var(--primary) 24%, transparent);
  }

  /* Thin themed scrollbars; .scrollbar-hide and inline scrollbarWidth: 'none' still win. */
  * {
    scrollbar-width: thin;
    scrollbar-color: var(--scrollbar-thumb) transparent;
  }
}

/* Fixed backdrop: its own composited layer, painted once. Scrolling only moves content above it. */
body::before {
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  content: '';
  background-color: var(--backdrop-base);
  background-image:
    var(--grain),
    radial-gradient(52% 44% at 8% 4%, var(--aurora-1), transparent 70%),
    radial-gradient(46% 40% at 96% 12%, var(--aurora-2), transparent 70%),
    radial-gradient(52% 46% at 88% 100%, var(--aurora-3), transparent 72%),
    radial-gradient(44% 42% at 2% 92%, var(--aurora-4), transparent 70%),
    linear-gradient(var(--backdrop-veil), var(--backdrop-veil)),
    url('/studio-nature-bg.webp');
  background-position: 0 0, center, center, center, center, center, center;
  background-repeat: repeat, no-repeat, no-repeat, no-repeat, no-repeat, no-repeat, no-repeat;
  background-size: 160px 160px, auto, auto, auto, auto, auto, cover;
  will-change: transform;
}

@layer components {
  /* Floating glass: menus, popovers, toasts, small toolbars. Solid where backdrop-filter is unsupported. */
  .nova-float {
    border: 1px solid var(--glass-edge);
    background-color: var(--popover);
    color: var(--popover-foreground);
    box-shadow: var(--nova-shadow-float);
  }

  /* Dialog sheet: full-screen and solid on phones (nothing behind it is visible), floating glass from sm up. */
  .nova-float-sheet {
    background-color: var(--popover);
    color: var(--popover-foreground);
  }

  @media (min-width: 640px) {
    .nova-float-sheet {
      border: 1px solid var(--glass-edge);
      box-shadow: var(--nova-shadow-float);
    }
  }

  @supports ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
    .nova-float {
      background-color: var(--glass-float);
      -webkit-backdrop-filter: blur(var(--float-blur)) saturate(1.6);
      backdrop-filter: blur(var(--float-blur)) saturate(1.6);
    }

    @media (min-width: 640px) {
      .nova-float-sheet {
        background-color: var(--glass-sheet);
        -webkit-backdrop-filter: blur(var(--sheet-blur)) saturate(1.5);
        backdrop-filter: blur(var(--sheet-blur)) saturate(1.5);
      }
    }
  }
}

@media (prefers-reduced-transparency: reduce) {
  .nova-float,
  .nova-float-sheet {
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }
}

/* ---------- Shell ---------- */
.nova-app-shell {
  background: transparent;
}

/* Normal mode: one floating glass card (mobile keeps the frame transparent via TSX). */
@media (min-width: 640px) {
  .nova-app-frame {
    border-color: var(--glass-edge);
    background: var(--glass-frame);
    box-shadow: var(--glass-shadow);
  }
}

/* Wide mode: sidebar and panels float directly on the backdrop. */
.nova-app-frame.nova-app-frame-wide {
  border-color: transparent;
  background: transparent;
  box-shadow: none;
}

.nova-studio-panel,
.nova-studio-history-panel,
.nova-agent-workspace {
  border-color: var(--glass-edge);
  background: var(--glass-panel);
  box-shadow: var(--glass-shadow);
}

/* Active-jobs panel keeps its processing tint on top of the glass. */
section.nova-studio-panel {
  border-color: color-mix(in srgb, var(--processing) 26%, var(--glass-edge));
  background:
    linear-gradient(color-mix(in srgb, var(--processing) 5%, transparent), color-mix(in srgb, var(--processing) 5%, transparent)),
    var(--glass-panel);
}

.nova-studio-history-panel {
  overflow: hidden;
  border: 1px solid var(--glass-edge);
  border-radius: 20px;
}

.nova-agent-workspace {
  border-radius: 20px;
}

.nova-agent-toolbar {
  border-color: var(--border);
  border-top-left-radius: inherit;
  border-top-right-radius: inherit;
  background: var(--glass-sheen);
}

.nova-agent-composer {
  border-color: var(--border);
  border-bottom-left-radius: inherit;
  border-bottom-right-radius: inherit;
  background: color-mix(in srgb, var(--surface) 70%, transparent);
}

@media (min-width: 640px) {
  .nova-gallery-panel {
    border-color: var(--glass-edge);
    background: var(--glass-panel);
    box-shadow: var(--glass-shadow);
  }
}

/* Settings is large and scrolls: a near-opaque static sheet, no live blur. */
.nova-app-settings {
  background: linear-gradient(180deg, var(--glass-card-a), var(--glass-card-b)), var(--popover);
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
}

@media (min-width: 640px) {
  .nova-app-settings {
    border-color: var(--glass-edge);
    border-radius: 20px;
  }
}

@media (min-width: 960px) {
  .nova-desktop-shell {
    min-height: 100dvh;
    gap: 0 !important;
    padding: 0 !important;
    background: transparent;
    animation: nova-desktop-enter 220ms ease-out both;
  }

  .nova-app-frame.nova-desktop-frame {
    overflow: hidden;
    border-radius: 18px;
    border-color: transparent;
    background: transparent;
    box-shadow: none;
  }

  .nova-desktop-inner {
    padding: 14px !important;
  }

  .nova-app-sidebar {
    width: 216px;
    flex-shrink: 0;
    padding: 6px 8px 10px;
    border: 1px solid var(--glass-edge);
    border-radius: 20px;
    background: var(--glass-chrome);
    box-shadow: var(--glass-shadow);
  }

  .nova-desktop-sidebar {
    width: 216px;
  }

  .nova-app-sidebar > button:first-child {
    margin-bottom: 4px;
    padding: 8px 9px 10px;
    border-radius: 12px;
  }

  .nova-app-sidebar [data-slot="tabs-list"] {
    gap: 2px;
    padding: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
  }

  .nova-app-sidebar [data-slot="tabs-trigger"] {
    min-height: 40px;
    gap: 10px;
    padding: 8px 10px 8px 14px;
    border: 1px solid transparent;
    border-radius: 12px;
    color: color-mix(in srgb, var(--foreground) 64%, var(--muted-foreground));
    transition: background-color 150ms ease, border-color 150ms ease, color 150ms ease, box-shadow 150ms ease;
  }

  .nova-app-sidebar [data-slot="tabs-trigger"]:hover {
    background: var(--surface);
    color: var(--foreground);
  }

  .nova-app-sidebar [data-slot="tabs-trigger"][data-active] {
    border-color: var(--glass-edge);
    background: var(--surface-strong);
    color: var(--foreground);
    box-shadow: var(--nova-shadow-lifted);
  }

  /* Small pill indicator instead of the old full-height inset bar. */
  .nova-app-sidebar [data-slot="tabs-trigger"][data-active]::before {
    position: absolute;
    top: 50%;
    left: 5px;
    width: 3px;
    height: 16px;
    border-radius: 999px;
    background: var(--primary);
    content: '';
    transform: translateY(-50%);
  }

  .nova-app-sidebar [data-slot="tabs-trigger"][data-active] svg {
    color: var(--primary);
  }

  .nova-desktop-sidebar-tools {
    margin-top: 4px;
    padding-top: 8px;
    border-top: 1px solid var(--border);
  }

  .nova-desktop-random button,
  .nova-desktop-sidebar-tools button {
    min-height: 34px;
    border-color: transparent;
    border-radius: 10px;
    background: transparent;
    box-shadow: none;
    color: var(--muted-foreground);
  }

  .nova-desktop-random button:hover,
  .nova-desktop-random button[aria-expanded="true"],
  .nova-desktop-sidebar-tools button:hover,
  .nova-desktop-sidebar-tools button[aria-expanded="true"] {
    background: var(--surface);
    color: var(--foreground);
  }

  .nova-desktop-status {
    margin-top: 6px;
    padding-top: 8px;
    border-top: 1px solid var(--border);
  }

  .nova-desktop-status > div > span {
    border-radius: 8px !important;
    background: var(--surface) !important;
  }

  .nova-desktop-topnav [data-slot="tabs-list"] {
    height: 52px;
    border: 1px solid var(--glass-edge);
    border-radius: 16px;
    background: var(--glass-chrome);
    box-shadow: var(--glass-shadow);
  }

  .nova-app-workspace {
    border: 1px solid var(--glass-edge);
    border-radius: 20px;
    background: var(--glass-frame);
    box-shadow: var(--glass-shadow);
  }

  /* Tabs whose content is already a set of glass panels drop the outer frame (no double glass). */
  .nova-app-workspace.nova-image-workspace,
  .nova-app-workspace.nova-workspace-bare {
    border-color: transparent;
    background: transparent;
    box-shadow: none;
  }

  .nova-desktop-workspace {
    min-width: 0;
