arguments.content:
/* ---------- Image generation workbench ---------- */
.studio-workbench-head {
  background: var(--glass-sheen);
}

.studio-params-bar {
  gap: 0.375rem;
}

.nova-image-workspace .studio-params-bar {
  flex-wrap: nowrap;
  overflow-x: auto;
  padding-bottom: 2px;
  scrollbar-width: none;
}

.nova-image-workspace .studio-params-bar::-webkit-scrollbar {
  display: none;
}

.nova-image-workspace .studio-params-bar > * {
  flex-shrink: 0;
}

.studio-params-bar [data-slot="button"] {
  border-color: var(--border);
  background: var(--surface);
}

.studio-params-bar [data-slot="button"]:hover {
  border-color: color-mix(in srgb, var(--primary) 32%, var(--border));
  background: color-mix(in srgb, var(--primary) 8%, var(--surface-hover));
}

.studio-prompt-surface {
  border-color: var(--input);
  background: var(--field);
  transition: border-color 150ms ease, box-shadow 150ms ease;
}

.studio-prompt-surface:focus-within {
  border-color: color-mix(in srgb, var(--primary) 50%, var(--input));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--primary) 14%, transparent);
}

.studio-reference-rail {
  transition: border-color 150ms ease, background-color 150ms ease;
}

.studio-reference-rail .group > button {
  border-radius: 0.5rem;
}

/* ---------- Results ---------- */
.studio-result-card {
  border-color: var(--border);
  background: var(--glass-card);
  box-shadow: inset 0 1px 0 var(--glass-highlight), 0 1px 2px rgb(var(--shadow-tint) / 0.05);
  transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
}

.studio-result-card:hover {
  border-color: color-mix(in srgb, var(--primary) 34%, var(--border));
  box-shadow: inset 0 1px 0 var(--glass-highlight), 0 12px 28px -12px rgb(var(--shadow-tint) / 0.3);
  transform: translateY(-2px);
}

.studio-result-toolbar {
  border-color: var(--border);
  background: color-mix(in srgb, var(--surface) 55%, transparent);
}

.studio-result-toolbar [data-slot="button"] {
  color: var(--muted-foreground);
}

.studio-result-toolbar [data-slot="button"]:hover {
  color: var(--foreground);
  background: color-mix(in srgb, var(--primary) 10%, var(--surface-hover));
}

.studio-waiting-card,
.studio-failed-card {
  background: var(--glass-card);
  box-shadow: inset 0 1px 0 var(--glass-highlight);
}

.studio-history-day-divider {
  min-height: 20px;
}

.studio-history-job,
.studio-waiting-card,
.studio-failed-card {
  animation: studio-history-enter 180ms ease-out both;
}

.studio-history-list-wide .studio-history-job {
  animation: none;
}

.studio-history-list-wide .studio-result-card:hover {
  transform: none;
}

.studio-history-list-wide .studio-result-media {
  aspect-ratio: 16 / 10;
}

.studio-history-list-wide .studio-result-content {
  padding: 0.625rem 0.625rem 0.5rem;
}

.studio-history-list-wide .studio-result-prompt {
  -webkit-line-clamp: 1;
}

.studio-history-list-wide .studio-result-toolbar {
  gap: 0;
  padding: 0.375rem 0.5rem;
}

.studio-history-list-wide .studio-failed-card {
  min-height: 148px;
}

.studio-active-empty {
  margin: 0 -0.75rem -0.75rem;
  background-image: linear-gradient(var(--empty-veil), var(--empty-veil)), url('/studio-nature-bg.webp');
  background-position: center, left 72%;
  background-size: auto, cover;
}

.studio-history-empty {
  min-height: 220px;
  border: 1px dashed var(--input);
  border-radius: 14px;
  background: color-mix(in srgb, var(--surface) 60%, transparent);
}

.studio-waiting-art::after {
  position: absolute;
  inset: 0;
