+  border-color: color-mix(in srgb, var(--primary) 32%, var(--border));
+  background: color-mix(in srgb, var(--primary) 8%, var(--surface-hover));
+}
+
+.studio-prompt-surface {
+  border-color: var(--input);
+  background: var(--field);
+  transition: border-color 150ms ease, box-shadow 150ms ease;
+}
+
+.studio-prompt-surface:focus-within {
+  border-color: color-mix(in srgb, var(--primary) 50%, var(--input));
+  box-shadow: 0 0 0 3px color-mix(in srgb, var(--primary) 14%, transparent);
+}
+
+.studio-reference-rail {
+  transition: border-color 150ms ease, background-color 150ms ease;
+}
+
+.studio-reference-rail .group > button {
+  border-radius: 0.5rem;
+}
+
+/* ---------- Results ---------- */
+.studio-result-card {
+  border-color: var(--border);
+  background: var(--glass-card);
+  box-shadow: inset 0 1px 0 var(--glass-highlight), 0 1px 2px rgb(var(--shadow-tint) / 0.05);
+  transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
+}
+
+.studio-result-card:hover {
+  border-color: color-mix(in srgb, var(--primary) 34%, var(--border));
+  box-shadow: inset 0 1px 0 var(--glass-highlight), 0 12px 28px -12px rgb(var(--shadow-tint) / 0.3);
+  transform: translateY(-2px);
+}
+
+.studio-result-toolbar {
+  border-color: var(--border);
+  background: color-mix(in srgb, var(--surface) 55%, transparent);
+}
+
+.studio-result-toolbar [data-slot="button"] {
+  color: var(--muted-foreground);
+}
+
+.studio-result-toolbar [data-slot="button"]:hover {
+  color: var(--foreground);
+  background: color-mix(in srgb, var(--primary) 10%, var(--surface-hover));
+}
+
+.studio-waiting-card,
+.studio-failed-card {
+  background: var(--glass-card);
+  box-shadow: inset 0 1px 0 var(--glass-highlight);
+}
+
+.studio-history-day-divider {
+  min-height: 20px;
+}
+
+.studio-history-job,
+.studio-waiting-card,
+.studio-failed-card {
+  animation: studio-history-enter 180ms ease-out both;
+}
+
+.studio-history-list-wide .studio-history-job {
+  animation: none;
+}
+
+.studio-history-list-wide .studio-result-card:hover {
+  transform: none;
+}
+
+.studio-history-list-wide .studio-result-media {
+  aspect-ratio: 16 / 10;
+}
+
+.studio-history-list-wide .studio-result-content {
+  padding: 0.625rem 0.625rem 0.5rem;
+}
+
+.studio-history-list-wide .studio-result-prompt {
+  -webkit-line-clamp: 1;
+}
+
+.studio-history-list-wide .studio-result-toolbar {
+  gap: 0;
+  padding: 0.375rem 0.5rem;
+}
+
+.studio-history-list-wide .studio-failed-card {
+  min-height: 148px;
+}
+
+.studio-active-empty {
+  margin: 0 -0.75rem -0.75rem;
+  background-image: linear-gradient(var(--empty-veil), var(--empty-veil)), url('/studio-nature-bg.webp');
+  background-position: center, left 72%;
+  background-size: auto, cover;
+}
+
+.studio-history-empty {
+  min-height: 220px;
+  border: 1px dashed var(--input);
+  border-radius: 14px;
+  background: color-mix(in srgb, var(--surface) 60%, transparent);
+}
+
+.studio-waiting-art::after {
+  position: absolute;
+  inset: 0;
+  background: linear-gradient(100deg, transparent 20%, color-mix(in srgb, var(--processing) 15%, transparent) 50%, transparent 80%);
+  content: '';
+  animation: studio-loading-sweep 1.8s ease-in-out infinite;
+}
+
+/* ---------- Queue ---------- */
+.nova-queue-summary {
+  min-width: 220px;
+}
+
+.nova-queue-summary-compact {
+  min-width: 0;
+}
+
+.nova-queue-metric {
+  display: flex;
+  min-width: 0;
+  flex-direction: column;
+  gap: 2px;
+  border: 1px solid var(--border);
+  border-radius: 10px;
+  padding: 7px 8px;
+  background: var(--surface);
+  box-shadow: var(--nova-shadow-raised);
+}
+
+.nova-queue-metric span {
+  color: var(--muted-foreground);
+  font-size: 10px;
+}
+
+.nova-queue-metric strong {
+  color: var(--foreground);
+  font-family: var(--nova-font-mono);
+  font-size: 13px;
+  font-weight: 600;
+  font-variant-numeric: tabular-nums;
+}
+
+.nova-queue-metric-alert strong {
+  color: var(--destructive);
+}
+
+.studio-model-catalog-item {
+  transition: background-color 150ms ease, border-color 150ms ease;
+}
+
+@keyframes studio-history-enter {
+  from { opacity: 0; transform: translateY(4px); }
+  to { opacity: 1; transform: translateY(0); }
+}
+
+@keyframes studio-loading-sweep {
+  from { transform: translateX(-100%); }
+  to { transform: translateX(100%); }
+}
+
+@media (max-width: 639px) {
+  .studio-reference-rail {
+    align-items: stretch;
+  }
+
+  .studio-reference-rail > :last-child {
+    justify-content: flex-end;
+  }
+}
+
+/* Normal mode keeps a deliberate reading width, so a single result does not fill a laptop screen. */
+@media (min-width: 640px) {
+  .studio-history-list:not(.studio-history-list-wide) .studio-history-day-group {
+    width: min(100%, 760px);
+    margin-inline: auto;
+  }
+}
+
+@media (min-width: 1280px) and (max-height: 820px) {
+  .nova-image-workspace .studio-workbench-head {
+    gap: 0.625rem;
+    padding-block: 0.625rem;
+  }
+
+  .nova-image-workspace .studio-prompt-surface textarea {
+    min-height: 8.5rem;
+  }
+
+  .nova-image-workspace .studio-reference-rail {
+    min-height: 4rem;
+  }
+}
+
+/* ---------- Motion ---------- */
+@keyframes nova-desktop-enter {
+  from {
+    opacity: 0;
+    transform: translateY(3px);
+  }
+  to {
+    opacity: 1;
+    transform: translateY(0);
+  }
+}
+
+@keyframes nova-rise {
+  from { opacity: 0; transform: translateY(6px); }
+}
+
+@keyframes nova-toast-in {
+  from { opacity: 0; transform: translateY(8px) scale(0.98); }
+}
+
+/* Entrance only: `backwards` fill leaves no lasting transform or stacking context once finished. */
+.nova-app-shell:not(.nova-desktop-shell) .nova-app-sidebar {
+  animation: nova-rise 320ms var(--ease-out-soft) backwards;
+}
+
+.nova-app-shell:not(.nova-desktop-shell) .nova-app-workspace {
+  animation: nova-rise 360ms var(--ease-out-soft) 50ms backwards;
+}
+
+.nova-toast {
+  animation: nova-toast-in 220ms var(--ease-out-soft) backwards;
+}
+
+@media (prefers-reduced-motion: reduce) {
+  .nova-desktop-shell,
+  .nova-app-shell:not(.nova-desktop-shell) .nova-app-sidebar,
+  .nova-app-shell:not(.nova-desktop-shell) .nova-app-workspace,
+  .nova-toast,
+  .studio-history-job,
+  .studio-waiting-card,
+  .studio-failed-card,
+  .studio-waiting-art::after {
+    animation: none;
+  }
+
+  .studio-result-card,
+  .studio-result-card:hover {
+    transform: none;
+  }
+}
+
+/* Shimmer animation for loading states */
+@keyframes shimmer {
+  0% {
+    transform: translateX(-100%);
+  }
+
+  100% {
+    transform: translateX(100%);
+  }
+}
+
+.animate-shimmer {
+  animation: shimmer 1.5s infinite;
+}
+
+/* Custom scrollbar for virtual scroll container (the old hsl(var(--hex)) values were invalid) */
+.virtual-scroll-container {
+  scrollbar-width: thin;
+  scrollbar-color: var(--scrollbar-thumb) transparent;
+}
+
+.virtual-scroll-container::-webkit-scrollbar {
+  width: 8px;
+}
+
+.virtual-scroll-container::-webkit-scrollbar-track {
+  background: transparent;
+  border-radius: 4px;
+}
+
+.virtual-scroll-container::-webkit-scrollbar-thumb {
+  background: var(--scrollbar-thumb);
+  border-radius: 4px;
+}
+
+/* Hide scrollbar but keep functionality */
+.scrollbar-hide {
+  -ms-overflow-style: none;
+  scrollbar-width: none;
+}
+
+.scrollbar-hide::-webkit-scrollbar {
+  display: none;
+}
+

