/*
 * `dark:` follows html[data-theme]; with no explicit theme it follows the OS.
 * (The previous `.dark *` variant never matched: nothing in the app sets a `.dark` class.)
 */
@custom-variant dark {
  &:where([data-theme="dark"], [data-theme="dark"] *) {
    @slot;
  }

  @media (prefers-color-scheme: dark) {
    &:where(:root:not([data-theme="light"]), :root:not([data-theme="light"]) *) {
      @slot;
    }
  }
}

