  --glass-frame: linear-gradient(160deg, var(--glass-frame-a), var(--glass-frame-b));
  --glass-panel: linear-gradient(160deg, var(--glass-panel-a), var(--glass-panel-b));
  --glass-card: linear-gradient(170deg, var(--glass-card-a), var(--glass-card-b));
  --glass-sheen: linear-gradient(180deg, var(--glass-sheen-a), transparent);
  --glass-float: var(--glass-float-bg);
  --glass-sheet: var(--glass-sheet-bg);
  --float-blur: 18px;
  --sheet-blur: 24px;
  --glass-shadow:
    0 0 0 1px var(--glass-hairline),
    inset 0 1px 0 var(--glass-highlight),
    0 1px 2px rgb(var(--shadow-tint) / 0.05),
    0 12px 32px -10px rgb(var(--shadow-tint) / 0.16);
  --glass-shadow-hover:
    0 0 0 1px var(--glass-hairline),
    inset 0 1px 0 var(--glass-highlight),
    0 2px 4px rgb(var(--shadow-tint) / 0.06),
    0 18px 40px -12px rgb(var(--shadow-tint) / 0.24);
  --nova-shadow-raised: inset 0 1px 0 var(--glass-highlight), 0 1px 2px rgb(var(--shadow-tint) / 0.06);
  --nova-shadow-lifted:
    inset 0 1px 0 var(--glass-highlight),
    0 1px 2px rgb(var(--shadow-tint) / 0.08),
    0 4px 12px -2px rgb(var(--shadow-tint) / 0.12);
  --nova-shadow-glow:
    inset 0 1px 0 rgb(255 255 255 / 0.22),
    0 1px 2px rgb(var(--shadow-tint) / 0.14),
    0 4px 14px -4px color-mix(in srgb, var(--primary) 55%, transparent);
  --nova-shadow-float:
    0 0 0 1px var(--glass-hairline),
    inset 0 1px 0 var(--glass-highlight),
    0 2px 6px rgb(var(--shadow-tint) / 0.08),
    0 16px 36px -8px rgb(var(--shadow-tint) / 0.22);
}

/* Windows "Transparency effects: off" (and similar OS settings): every glass surface turns solid. */
@media (prefers-reduced-transparency: reduce) {
  :root {
    --glass-chrome: var(--glass-solid);
    --glass-frame: var(--glass-solid);
    --glass-panel: var(--glass-solid);
    --glass-card: var(--glass-solid);
    --glass-float: var(--glass-solid);
    --glass-sheet: var(--glass-solid);
  }
}

