arguments.content:
// Compile frontend/src/app/globals.css with the project's own Tailwind (no build), and print a few probes.
const fs = require('fs');
const path = require('path');

const root = process.argv[2];
const outDir = process.argv[3];
const req = (m) => require(require.resolve(m, { paths: [root] }));
const postcss = req('postcss');
const tailwind = req('@tailwindcss/postcss');

const from = path.join(root, 'src', 'app', 'globals.css');
postcss([tailwind({ base: root })])
  .process(fs.readFileSync(from, 'utf8'), { from })
  .then((result) => {
    const out = result.css;
    fs.writeFileSync(path.join(outDir, 'compiled.css'), out);
    console.log('compiled bytes', out.length);
    const at = (needle, len = 420) => {
      const i = out.indexOf(needle);
      console.log(`--- ${needle}`, i < 0 ? 'NOT FOUND' : `\n${out.slice(i, i + len)}`);
    };
    for (const needle of process.argv.slice(4)) at(needle);
    for (const warning of result.warnings()) console.log('WARN', warning.toString());
  })
  .catch((error) => {
    console.error('CSS ERROR', error.message);
    process.exit(1);
  });

