+++ b/C:/Users/gongnan/AppData/Local/Temp/nova-ui-bench/image-api-test.mjs
@@ -0,0 +1,252 @@
+// Reproduce nova-image-studio's GPT image request against a live endpoint and compare it with a minimal
+// standard OpenAI Images call. The API key comes from NOVA_TEST_KEY and is masked in all output.
+// Response handling below is copied from backend/server.js so the "nova parser" verdict matches the app.
+import fs from 'node:fs/promises';
+import path from 'node:path';
+
+const KEY = process.env.NOVA_TEST_KEY || '';
+if (!KEY) { console.error('NOVA_TEST_KEY missing'); process.exit(2); }
+const BASE = String(process.env.NOVA_TEST_BASE || 'https://aioss.cc').trim().replace(/\/+$/, '').replace(/\/v1$/, '');
+const MODEL = process.env.NOVA_TEST_MODEL || 'gpt-image-2.5-flare';
+const SIZE = process.env.NOVA_TEST_SIZE || '1024x1024';
+const OUT = path.join(process.env.TEMP || '.', 'nova-ui-bench', 'image-api-test');
+const PROMPT = 'A single green leaf on a plain white background, minimal product photo';
+const mask = (value) => String(value ?? '').split(KEY).join('sk-***');
+const log = (...parts) => console.log(mask(parts.map(p => (typeof p === 'string' ? p : JSON.stringify(p))).join(' ')));
+
+// ---- copied from backend/server.js ----
+const IMAGE_STREAM_UNSUPPORTED_PATTERN = /(?:(?:stream|partial_images).*(?:unsupported|not supported|unknown|unrecognized|invalid)|(?:unsupported|not supported|unknown|unrecognized|invalid).*(?:stream|partial_images)|(?:stream|partial_images).*(?:不支持|未知|无效)|(?:不支持|未知|无效).*(?:stream|partial_images))/i;
+function parseJsonSafely(text) { try { return JSON.parse(text); } catch { return null; } }
+function isLikelyHtmlResponse(text) {
+  const trimmed = String(text || '').trim().toLowerCase();
+  return trimmed.startsWith('<!doctype html') || trimmed.startsWith('<html') || trimmed.startsWith('<head') || trimmed.startsWith('<body');
+}
+function summarizeUnexpectedResponse(text) {
+  const trimmed = String(text || '').trim();
+  if (!trimmed) return '';
+  if (isLikelyHtmlResponse(trimmed)) return '上游返回了 HTML 页面而不是 JSON。';
+  return trimmed.length > 200 ? `${trimmed.slice(0, 200)}…` : trimmed;
+}
+function getMessageFromPayload(payload) {
+  if (!payload || typeof payload !== 'object') return '';
+  if (typeof payload.message === 'string' && payload.message.trim()) return payload.message.trim();
+  const error = payload.error;
+  if (typeof error === 'string' && error.trim()) return error.trim();
+  if (error && typeof error === 'object') {
+    if (typeof error.message === 'string' && error.message.trim()) return error.message.trim();
+    if (typeof error.code === 'string' && error.code.trim()) return error.code.trim();
+  }
+  return '';
+}
+function getErrorMessageFromPayload(payload) {
+  if (!payload || typeof payload !== 'object') return '';
+  if (payload.error) return getMessageFromPayload(payload);
+  const type = typeof payload.type === 'string' ? payload.type.toLowerCase() : '';
+  if (type === 'error' || type === 'upstream_error') return getMessageFromPayload(payload);
+  return '';
+}
+function getUpstreamErrorText(text) {
+  const trimmed = String(text || '').trim();
+  const data = parseJsonSafely(trimmed);
+  const message = getErrorMessageFromPayload(data) || getMessageFromPayload(data);
+  if (message) return message;
+  return trimmed.length > 500 ? `${trimmed.slice(0, 500)}…` : trimmed;
+}
+function normalizeImagePayloadValue(imageData) {
+  if (!imageData || typeof imageData !== 'string') return undefined;
+  if (imageData.startsWith('data:image')) return imageData.split(',')[1] || imageData;
+  if (/^https?:\/\//i.test(imageData)) return `URL:${imageData}`;
+  return imageData;
+}
+function getImagePayloadValue(data, depth = 0) {
+  if (!data || depth > 3) return undefined;
+  if (Array.isArray(data)) {
+    for (const item of data) { const value = getImagePayloadValue(item, depth + 1); if (value) return value; }
+    return undefined;
+  }
+  if (typeof data !== 'object') return undefined;
+  const firstImage = Array.isArray(data.data)
+    ? data.data.find(item => item && typeof item === 'object' && (item.b64_json || item.url || item.image_url))
+    : undefined;
+  const imageData = firstImage?.b64_json || firstImage?.url || firstImage?.image_url || data.b64_json || data.url || data.image_url;
+  if (imageData) return imageData;
+  return getImagePayloadValue(data.result, depth + 1) || getImagePayloadValue(data.response, depth + 1) || getImagePayloadValue(data.output, depth + 1);
+}
+function extractImagePayload(data) {
+  const imageData = normalizeImagePayloadValue(getImagePayloadValue(data));
+  if (!imageData) throw new Error('响应中无图片数据');
+  return imageData;
+}
+function parseImageEventStream(text) {
+  const payloads = [];
+  let dataLines = [];
+  const flush = () => {
+    if (dataLines.length === 0) return;
+    const raw = dataLines.join('\n').trim();
+    dataLines = [];
+    if (!raw || raw === '[DONE]') return;
+    const parsed = parseJsonSafely(raw);
+    if (parsed) payloads.push(parsed);
+  };
+  for (const rawLine of String(text || '').split(/\r?\n/)) {
+    const line = rawLine.trimEnd();
+    if (line === '') { flush(); continue; }
+    if (line.startsWith(':')) continue;
+    if (line.startsWith('data:')) dataLines.push(line.slice(5).trimStart());
+  }
+  flush();
+  return payloads;
+}
+function isPartialImageEvent(payload) {
+  const type = typeof payload?.type === 'string' ? payload.type.toLowerCase() : '';
+  return type.includes('partial');
+}
+function extractImagePayloadFromEventStream(text) {
+  const payloads = parseImageEventStream(text);
+  const errorMessage = payloads.map(getErrorMessageFromPayload).find(Boolean);
+  for (const payload of [...payloads].reverse()) {
+    if (isPartialImageEvent(payload)) continue;
+    try { return extractImagePayload(payload); } catch { /* keep scanning */ }
+  }
+  if (errorMessage) throw new Error(errorMessage);
+  throw new Error('响应中无图片数据');
+}
+function projectParse(status, ok, contentType, text) {
+  if (!ok) {
+    const errorText = getUpstreamErrorText(text);
+    throw new Error(`API 请求失败: ${status}${errorText ? ` ${errorText}` : ''}`);
+  }
+  if (contentType.includes('text/event-stream')) return extractImagePayloadFromEventStream(text);
+  if (isLikelyHtmlResponse(text)) throw new Error('上游返回了 HTML 页面而不是 JSON。');
+  const data = parseJsonSafely(text);
+  if (!data) { const summary = summarizeUnexpectedResponse(text); throw new Error(summary ? `响应 JSON 格式无效: ${summary}` : '响应 JSON 格式无效'); }
+  const errorMessage = getErrorMessageFromPayload(data);
+  if (errorMessage) throw new Error(errorMessage);
+  return extractImagePayload(data);
+}
+// ---- end copy ----
+
+function shape(v, depth = 0) {
+  if (Array.isArray(v)) return depth > 4 ? `[${v.length}]` : v.slice(0, 4).map(x => shape(x, depth + 1)).concat(v.length > 4 ? [`+${v.length - 4}`] : []);
+  if (v && typeof v === 'object') return depth > 4 ? '{…}' : Object.fromEntries(Object.entries(v).map(([k, x]) => [k, shape(x, depth + 1)]));
+  if (typeof v === 'string') return v.length > 120 ? `<str ${v.length}${/^(iVBOR|\/9j\/|UklGR|data:image)/.test(v) ? ' image-b64' : ''}>` : v;
+  return v;
+}
+function findImages(v, p = '$', out = []) {
+  if (typeof v === 'string') {
+    if (/^data:image\//.test(v) || (v.length > 1000 && /^(iVBOR|\/9j\/|UklGR|R0lGOD)/.test(v))) out.push(`${p} b64(${v.length})`);
+    else if (/^https?:\/\/\S+$/i.test(v)) out.push(`${p} url`);
+    else if (/!\[[^\]]*\]\((https?:\/\/|data:image)/.test(v)) out.push(`${p} markdown-image`);
+  } else if (Array.isArray(v)) v.forEach((x, i) => findImages(x, `${p}[${i}]`, out));
+  else if (v && typeof v === 'object') for (const [k, x] of Object.entries(v)) findImages(x, `${p}.${k}`, out);
+  return out;
+}
+function compress(list) {
+  const out = [];
+  for (const item of list) { const last = out.at(-1); if (last && last[0] === item) last[1]++; else out.push([item, 1]); }
+  return out.map(([item, n]) => (n > 1 ? `${item} x${n}` : item)).join(', ');
+}
+function imageInfo(b64) {
+  const buf = Buffer.from(b64, 'base64');
+  if (buf.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]))) return { type: 'png', width: buf.readUInt32BE(16), height: buf.readUInt32BE(20), buf };
+  if (buf[0] === 0xff && buf[1] === 0xd8) return { type: 'jpeg', buf };
+  if (buf.subarray(0, 4).toString() === 'RIFF' && buf.subarray(8, 12).toString() === 'WEBP') return { type: 'webp', buf };
+  return { type: `unknown(${buf.subarray(0, 8).toString('hex')})`, buf };
+}
+
+const TESTS = {
+  standard: { desc: 'minimal standard call (no stream, no extras)', body: { model: MODEL, prompt: PROMPT, n: 1, size: SIZE } },
+  project: { desc: 'exact nova request (stream + partial_images + quality/background/output_format)', body: { prompt: PROMPT, model: MODEL, stream: true, partial_images: 1, size: SIZE, quality: 'auto', background: 'auto', output_format: 'png' } },
+  'project-nostream': { desc: 'nova extras without stream', body: { prompt: PROMPT, model: MODEL, size: SIZE, quality: 'auto', background: 'auto', output_format: 'png' } },
+  'stream-only': { desc: 'stream + partial_images, no extras', body: { prompt: PROMPT, model: MODEL, stream: true, partial_images: 1, size: SIZE } },
+};
+
+async function probe() {
+  const alt = BASE.includes('://www.') ? BASE.replace('://www.', '://') : BASE.replace('://', '://www.');
+  for (const base of [BASE, alt]) {
+    log(`\n== ${base} ==`);
+    try {
+      const r = await fetch(`${base}/v1/models`, { headers: { Authorization: `Bearer ${KEY}` }, redirect: 'manual', signal: AbortSignal.timeout(30000) });
+      const text = await r.text();
+      const data = parseJsonSafely(text);
+      const ids = Array.isArray(data?.data) ? data.data.map(m => m?.id).filter(Boolean) : [];
+      log(`GET /v1/models -> ${r.status} ${r.headers.get('content-type') || ''} location=${r.headers.get('location') || '-'} models=${ids.length} has(${MODEL})=${ids.includes(MODEL)}`);
+      const imageIds = ids.filter(id => /image|img|dall|flux|seedream|imagen|grok/i.test(id));
