+  flush();
+  return payloads;
+}
+function isPartialImageEvent(payload) {
+  const type = typeof payload?.type === 'string' ? payload.type.toLowerCase() : '';
+  return type.includes('partial');
+}
+function extractImagePayloadFromEventStream(text) {
+  const payloads = parseImageEventStream(text);
+  const errorMessage = payloads.map(getErrorMessageFromPayload).find(Boolean);
+  for (const payload of [...payloads].reverse()) {
+    if (isPartialImageEvent(payload)) continue;
+    try { return extractImagePayload(payload); } catch { /* keep scanning */ }
+  }
+  if (errorMessage) throw new Error(errorMessage);
+  throw new Error('响应中无图片数据');
+}
+function projectParse(status, ok, contentType, text) {
+  if (!ok) {
+    const errorText = getUpstreamErrorText(text);
+    throw new Error(`API 请求失败: ${status}${errorText ? ` ${errorText}` : ''}`);
+  }
+  if (contentType.includes('text/event-stream')) return extractImagePayloadFromEventStream(text);
+  if (isLikelyHtmlResponse(text)) throw new Error('上游返回了 HTML 页面而不是 JSON。');
+  const data = parseJsonSafely(text);
+  if (!data) { const summary = summarizeUnexpectedResponse(text); throw new Error(summary ? `响应 JSON 格式无效: ${summary}` : '响应 JSON 格式无效'); }
+  const errorMessage = getErrorMessageFromPayload(data);
+  if (errorMessage) throw new Error(errorMessage);
+  return extractImagePayload(data);
+}
+// ---- end copy ----
+
+function shape(v, depth = 0) {
+  if (Array.isArray(v)) return depth > 4 ? `[${v.length}]` : v.slice(0, 4).map(x => shape(x, depth + 1)).concat(v.length > 4 ? [`+${v.length - 4}`] : []);
+  if (v && typeof v === 'object') return depth > 4 ? '{…}' : Object.fromEntries(Object.entries(v).map(([k, x]) => [k, shape(x, depth + 1)]));
+  if (typeof v === 'string') return v.length > 120 ? `<str ${v.length}${/^(iVBOR|\/9j\/|UklGR|data:image)/.test(v) ? ' image-b64' : ''}>` : v;
+  return v;
+}
+function findImages(v, p = '$', out = []) {
+  if (typeof v === 'string') {
+    if (/^data:image\//.test(v) || (v.length > 1000 && /^(iVBOR|\/9j\/|UklGR|R0lGOD)/.test(v))) out.push(`${p} b64(${v.length})`);
+    else if (/^https?:\/\/\S+$/i.test(v)) out.push(`${p} url`);
+    else if (/!\[[^\]]*\]\((https?:\/\/|data:image)/.test(v)) out.push(`${p} markdown-image`);
+  } else if (Array.isArray(v)) v.forEach((x, i) => findImages(x, `${p}[${i}]`, out));
+  else if (v && typeof v === 'object') for (const [k, x] of Object.entries(v)) findImages(x, `${p}.${k}`, out);
+  return out;
+}
+function compress(list) {
+  const out = [];
+  for (const item of list) { const last = out.at(-1); if (last && last[0] === item) last[1]++; else out.push([item, 1]); }
+  return out.map(([item, n]) => (n > 1 ? `${item} x${n}` : item)).join(', ');
+}
+function imageInfo(b64) {
+  const buf = Buffer.from(b64, 'base64');
+  if (buf.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]))) return { type: 'png', width: buf.readUInt32BE(16), height: buf.readUInt32BE(20), buf };
+  if (buf[0] === 0xff && buf[1] === 0xd8) return { type: 'jpeg', buf };
+  if (buf.subarray(0, 4).toString() === 'RIFF' && buf.subarray(8, 12).toString() === 'WEBP') return { type: 'webp', buf };
+  return { type: `unknown(${buf.subarray(0, 8).toString('hex')})`, buf };
+}
+
+const TESTS = {
+  standard: { desc: 'minimal standard call (no stream, no extras)', body: { model: MODEL, prompt: PROMPT, n: 1, size: SIZE } },
+  project: { desc: 'exact nova request (stream + partial_images + quality/background/output_format)', body: { prompt: PROMPT, model: MODEL, stream: true, partial_images: 1, size: SIZE, quality: 'auto', background: 'auto', output_format: 'png' } },
+  'project-nostream': { desc: 'nova extras without stream', body: { prompt: PROMPT, model: MODEL, size: SIZE, quality: 'auto', background: 'auto', output_format: 'png' } },
+  'stream-only': { desc: 'stream + partial_images, no extras', body: { prompt: PROMPT, model: MODEL, stream: true, partial_images: 1, size: SIZE } },
+};
+
+async function probe() {
+  const alt = BASE.includes('://www.') ? BASE.replace('://www.', '://') : BASE.replace('://', '://www.');
+  for (const base of [BASE, alt]) {
+    log(`\n== ${base} ==`);
+    try {
+      const r = await fetch(`${base}/v1/models`, { headers: { Authorization: `Bearer ${KEY}` }, redirect: 'manual', signal: AbortSignal.timeout(30000) });
+      const text = await r.text();
+      const data = parseJsonSafely(text);
+      const ids = Array.isArray(data?.data) ? data.data.map(m => m?.id).filter(Boolean) : [];
+      log(`GET /v1/models -> ${r.status} ${r.headers.get('content-type') || ''} location=${r.headers.get('location') || '-'} models=${ids.length} has(${MODEL})=${ids.includes(MODEL)}`);
+      const imageIds = ids.filter(id => /image|img|dall|flux|seedream|imagen|grok/i.test(id));
+      if (imageIds.length) log('  image-like models:', imageIds.slice(0, 40).join(', '));
+      if (!ids.length) log('  body:', getUpstreamErrorText(text).slice(0, 200));
+    } catch (e) { log('GET /v1/models failed:', e.name, e.message, e.cause?.code || ''); }
+    try {
+      const r = await fetch(`${base}/v1/images/generations`, { method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${KEY}` }, body: '{}', redirect: 'manual', signal: AbortSignal.timeout(30000) });
+      const text = await r.text();
+      log(`POST /v1/images/generations (empty body, no redirect follow) -> ${r.status} ${r.headers.get('content-type') || ''} location=${r.headers.get('location') || '-'} msg=${getUpstreamErrorText(text).slice(0, 200)}`);
+    } catch (e) { log('POST probe failed:', e.name, e.message, e.cause?.code || ''); }
+  }
+}
+
+async function runTest(name) {
+  const t = TESTS[name];
+  if (!t) { log('unknown test', name); return { name, ok: false, error: 'unknown test' }; }
+  const url = `${BASE}/v1/images/generations`;
+  log(`\n== ${name}: ${t.desc}\n   POST ${url} body=${JSON.stringify({ ...t.body, prompt: '<prompt>' })}`);
+  const t0 = Date.now();
+  let res;
+  try {
+    res = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${KEY}` }, body: JSON.stringify(t.body), signal: AbortSignal.timeout(10 * 60 * 1000) });
+  } catch (e) {
+    log(`   fetch failed after ${Date.now() - t0}ms:`, e.name, e.message, e.cause?.code || e.cause?.message || '');
+    return { name, ok: false, error: `fetch: ${e.message}` };
+  }
+  const contentType = String(res.headers.get('content-type') || '').toLowerCase();
+  log(`   -> ${res.status} ${contentType} headers@${Date.now() - t0}ms redirected=${res.redirected} finalUrl=${res.url} server=${res.headers.get('server') || '-'}`);
+  let text = '';
+  try { text = await res.text(); } catch (e) {
+    log(`   body read failed after ${Date.now() - t0}ms:`, e.name, e.message, e.cause?.code || '');
+    return { name, ok: false, error: `body: ${e.message}` };
+  }
+  log(`   body ${Buffer.byteLength(text)} bytes @${Date.now() - t0}ms`);
+  const looksSse = contentType.includes('text/event-stream') || /^\s*(data:|event:)/.test(text);
+  if (looksSse) {
+    const events = parseImageEventStream(text);
+    log(`   SSE events=${events.length} types=${compress(events.map(e => e?.type || '(no type)'))}`);
+    const last = events.filter(e => !isPartialImageEvent(e)).at(-1) ?? events.at(-1);
+    if (last) log('   last non-partial event shape:', shape(last));
+    const other = text.split(/\r?\n/).filter(l => l && !l.startsWith('data:')).slice(0, 4);
+    if (other.length) log('   non-data lines:', other.map(l => l.slice(0, 80)));
+  } else {
+    const data = parseJsonSafely(text);
+    log('   JSON shape:', data ? shape(data) : `(not JSON) ${summarizeUnexpectedResponse(text)}`);
+  }
+  const parsed = parseJsonSafely(text);
+  const found = parsed ? findImages(parsed) : parseImageEventStream(text).flatMap((e, i) => findImages(e, `$event[${i}]`));
+  log('   images anywhere (lenient scan):', found.length ? found.slice(0, 6) : 'none');
+  try {
+    const value = projectParse(res.status, res.ok, contentType, text);
+    if (value.startsWith('URL:')) {
+      const imageUrl = value.slice(4);
+      const r = await fetch(imageUrl, { signal: AbortSignal.timeout(60000) });
+      const buf = Buffer.from(await r.arrayBuffer());
+      log(`   nova parser: OK (URL result) download -> ${r.status} ${r.headers.get('content-type') || ''} ${buf.length} bytes`);
+    } else {
+      const info = imageInfo(value);
+      const file = path.join(OUT, `${name}.${info.type.startsWith('unknown') ? 'bin' : info.type}`);
+      await fs.writeFile(file, info.buf);
+      log(`   nova parser: OK ${info.type}${info.width ? ` ${info.width}x${info.height}` : ''} ${info.buf.length} bytes -> ${file}`);
+    }
+    return { name, ok: true, ms: Date.now() - t0 };
+  } catch (e) {
+    const fallback = IMAGE_STREAM_UNSUPPORTED_PATTERN.test(e.message);
+    log(`   nova parser: FAIL "${String(e.message).slice(0, 300)}"${t.body.stream ? ` | non-stream fallback would ${fallback ? '' : 'NOT '}trigger` : ''}`);
+    return { name, ok: false, error: e.message, ms: Date.now() - t0 };
+  }
+}
+
+await fs.mkdir(OUT, { recursive: true });
+log(`base=${BASE} model=${MODEL} size=${SIZE} key=sk-***(${KEY.length} chars) node=${process.version}`);
+const phase = process.argv[2] || 'probe';
+if (phase === 'probe') {
+  await probe();
+} else {
+  const results = [];
+  for (const name of (process.argv[3] || 'standard,project').split(',')) results.push(await runTest(name));
+  log('\nSUMMARY', results.map(r => `${r.name}=${r.ok ? 'OK' : 'FAIL'}${r.ms ? `(${Math.round(r.ms / 1000)}s)` : ''}`).join(' '));
+}

