  if (!response.ok) {
    const detail = await response.text().catch(() => '');
    return {
      modelId: model.id,
      actualName: model.name,
      available: false,
      message: `${response.status}${detail ? ` ${detail.slice(0, 120)}` : ''}`,
    };
  }
  const data = await response.json().catch(() => ({})) as {
    data?: Array<{ id?: string; model?: string }>;
    models?: Array<{ name?: string }>;
  };
  const exists = (
    (Array.isArray(data.data) && data.data.some(
      (item) => String(item?.id || item?.model || '') === model.modelId,
    ))
    || (Array.isArray(data.models) && data.models.some(
      (item) => String(item?.name || '').replace(/^models\//, '') === model.modelId,
    ))
  );
  return {
    modelId: model.id,
    actualName: model.name,
    available: exists,
    message: exists ? model.modelId : `未在模型列表中找到 ${model.modelId}（部分中转站不会列出全部模型，不代表一定不能生成）`,
  };
} catch (error) {
  const timedOut = error instanceof DOMException && error.name === 'TimeoutError';
  return {
    modelId: model.id,
    actualName: model.name,
    available: false,
    message: timedOut ? '检查超时（20 秒），地址可能无法访问' : getErrorMessage(error),
  };
}

