      if (text.indexOf('\n\n', from) !== -1 || text.indexOf('\r\n\r\n', from) !== -1) {
        eventEndAt = now;
        eventEndBytes = bytes;
        log(`[${at(now)}] completed event fully received (${mb(bytes)})`);
      }
    }
