# Read-only: recent tasks with duration and the real format of each saved result file (magic bytes).
import json
import os
import pathlib
import sqlite3
import struct
from datetime import datetime

ROOT = pathlib.Path(os.environ["LOCALAPPDATA"]) / "Nova Image Studio"


def ts(value):
    try:
        return datetime.fromisoformat(str(value).replace("Z", "+00:00"))
    except (TypeError, ValueError):
        return None


def describe(p):
    head = p.read_bytes()[:32]
    if head[:8] == b"\x89PNG\r\n\x1a\n":
        w, h = struct.unpack(">II", head[16:24])
        return f"png {w}x{h}"
    if head[:3] == b"\xff\xd8\xff":
        return "jpeg"
    if head[:4] == b"RIFF" and head[8:12] == b"WEBP":
        return "webp"
    return "other " + head[:8].hex()


files = {}
img_dir = ROOT / "runtime" / "task-images"
if img_dir.exists():
    for p in img_dir.iterdir():
        if p.is_file():
            files.setdefault(p.name[:36], []).append(p)

con = sqlite3.connect((ROOT / "data" / "tasks.sqlite").resolve().as_uri() + "?mode=ro", uri=True)
for tid, status, created, completed, req in con.execute(
    "SELECT id, status, created_at, completed_at, request_json FROM tasks ORDER BY created_at DESC LIMIT 10"
):
    r = json.loads(req or "{}")
    a, b = ts(created), ts(completed)
    took = f"{(b - a).total_seconds():.0f}s" if a and b else "running"
    info = ", ".join(f"{p.suffix} {describe(p)} {p.stat().st_size / 1048576:.2f}MB" for p in files.get(tid, [])) or "-"
    print(f"{a.astimezone().strftime('%H:%M:%S') if a else '-'} -> {b.astimezone().strftime('%H:%M:%S') if b else '-'} "
          f"{took:>7} {status:<9} {r.get('model'):<24} {str(r.get('baseUrl')):<22} {r.get('outputSize')}/{r.get('aspectRatio')}  {info}")
con.close()

